BukhariBab(bookNumber: 10, babNumber: 40, startHadith: 666, endHadith: 667, title: 'বৃষ্টি ও ওজরবশত নিজ আবাসস্থলে সালাত আদায়ের অনুমতি।', arabic: ''),
BukhariBab(bookNumber: 10, babNumber: 41, startHadith: 668, endHadith: 670, title: 'যারা উপস্থিত হয়েছে তাদের নিয়েই কি সালাত আদায় করবে এবং বৃষ্টির দিনে কি জুমু‘আহর খুতবাহ পড়বে?', arabic: ''),
BukhariBab(bookNumber: 10, babNumber: 42, startHadith: 671, endHadith: 674, title: 'খাবার উপস্থিত হবার পর যদি সালাতের ইক্বামাত হয়।', arabic: ''),
