BukhariBab(bookNumber: 10, babNumber: 44, startHadith: 676, endHadith: 676, title: 'ঘরের কাজ-কর্মে ব্যস্ত থাকা অবস্থায় ইক্বামাত হলে, সালাতের জন্য বের হয়ে যাবে।', arabic: ''),
BukhariBab(bookNumber: 10, babNumber: 45, startHadith: 677, endHadith: 677, title: 'যে ব্যক্তি কেবলমাত্র আল্লাহর রসূল ﷺ-এর সালাত ও তাঁর নিয়ম নীতি শিক্ষা দেয়ার উদ্দেশে লোকদের নিয়ে সালাত আদায় করেন।', arabic: ''),
BukhariBab(bookNumber: 10, babNumber: 46, startHadith: 678, endHadith: 682, title: 'বিজ্ঞ ও মর্যাদাশীল ব্যক্তিই ইমামাতের অধিক যোগ্য।', arabic: ''),
BukhariBab(bookNumber: 10, babNumber: 47, startHadith: 683, endHadith: 683, title: 'কারণবশত ইমামের পাশে দাঁড়ানো।', arabic: ''),
