BukhariBab(bookNumber: 10, babNumber: 49, startHadith: 685, endHadith: 685, title: 'কয়েক ব্যক্তি কিরা‘আত পাঠে সমান হলে, তাদের মধ্যে বয়সে বড় ব্যক্তি ইমাম হবেন।', arabic: ''),
