BukhariBab(bookNumber: 10, babNumber: 51, startHadith: 687, endHadith: 689, title: 'ইমাম নির্ধারণ করা হয় অনুসরণ করার জন্য।', arabic: ''),
BukhariBab(bookNumber: 10, babNumber: 52, startHadith: 690, endHadith: 690, title: 'মুক্তাদীগণ কখন সিজদা্তে যাবেন?', arabic: ''),
BukhariBab(bookNumber: 10, babNumber: 53, startHadith: 691, endHadith: 691, title: 'ইমামের পূর্বে মাথা উঠানো গুনাহ।', arabic: ''),
