BukhariBab(bookNumber: 10, babNumber: 56, startHadith: 695, endHadith: 696, title: 'ফিতনাবাজ ও বিদ্‘আতীর ইমামাত।', arabic: ''),
BukhariBab(bookNumber: 10, babNumber: 57, startHadith: 697, endHadith: 697, title: 'দু’জন সালাত আদায় করলে, মুক্তাদী ইমামের ডানপাশে সোজাসুজি দাঁড়াবে।', arabic: ''),
