BukhariBab(bookNumber: 19, babNumber: 10, startHadith: 1137, endHadith: 1140, title: 'নাবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর সালাত কিরূপ ছিল এবং রাতে তিনি কত রাক‘আত সালাত আদায় করতেন?', arabic: ''),
BukhariBab(bookNumber: 19, babNumber: 11, startHadith: 1141, endHadith: 1141, title: 'নাবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর ইবাদাতে রাত জাগরণ এবং তাঁর ঘুমানো আর রাত জাগার যতটুকু রহিত করা হয়েছে।', arabic: ''),
