BukhariBab(bookNumber: 25, babNumber: 33, startHadith: 1560, endHadith: 1560, title: 'মহান আল্লাহর বাণীঃ ‘‘হজ্জ হয় সুবিদিত মাসগুলোতে। অতঃপর যে কেউ এ মাসগুলোতে হজ্জ করা স্থির করে, তার জন্য হজ্জের সময়ে স্ত্রী সম্ভোগ, অন্যায় আচরণ ও কলহ বিবাদ বিধেয় নয়’’- (আল-বাকারাঃ ১৯৭)।', arabic: ''),
