BukhariBab(bookNumber: 25, babNumber: 101, startHadith: 1685, endHadith: 1687, title: 'কুরবানীর দিবসে সকালে জামরায়ে ‘আকাবাতে কঙ্কর নিক্ষেপের সময় তাকবীর ও তালবিয়া পাঠ করা এবং চলার পথে কাউকে সওয়ারীতে পেছনে বসানো।', arabic: ''),
BukhariBab(bookNumber: 25, babNumber: 102, startHadith: 1688, endHadith: 1688, title: '‘‘আর তোমাদের মধ্যে যারা হজ্জ ও ‘উমরাহ একত্রে একই সঙ্গে পালন করতে চায়, তাহলে যা কিছু সহজলভ্য, তা দিয়ে কুরবানী করাই তার উপর কর্তব্য। বস্তুত যারা কুরবানীর পশু পাবে না, তারা হজ্জের দিনগুলোর মধ্যে তিনটি সওম পালন করবে এবং সাতটি পালন করবে ফিরে যাবার পর। এভাবে দশটি সিয়াম পূর্ণ হয়ে যাবে। এ নির্দেশটি তাদের জন্য যাদের পরিবার-পরিজন মসজিদুল হারামের আশেপাশে বসবাস করে না।’’ (আল-বাকারাঃ ১৯৬)', arabic: ''),
