    BukhariBab(bookNumber: 34, babNumber: 109, startHadith: 2229, endHadith: 2229, title: 'কৃতদাসীদের বিক্রয় করার বিবরণ।', arabic: ''),
    BukhariBab(bookNumber: 34, babNumber: 110, startHadith: 2230, endHadith: 2234, title: 'মুদাবিবর (মনিবের মৃত্যুর পর যে কৃতদাস আযাদ হবে) বিক্রির বর্ণনা।', arabic: ''),
    BukhariBab(bookNumber: 34, babNumber: 111, startHadith: 2235, endHadith: 2236, title: 'ইসতিবরা অর্থাৎ জরায়ু গর্ভমুক্ত কি-না তা অবগত হওয়ার আগে দাসীকে নিয়ে ভ্রমণে বের হওয়া যায় কিনা।', arabic: ''),
    BukhariBab(bookNumber: 34, babNumber: 113, startHadith: 2237, endHadith: 2238, title: 'কুকুরের বিনিময়।', arabic: ''),
    BukhariBab(bookNumber: 35, babNumber: 1, startHadith: 2239, endHadith: 2239, title: 'মাপ বা নির্দিষ্ট পরিমাপে অগ্রিম ক্রয়-বিক্রয়।', arabic: ''),
    BukhariBab(bookNumber: 35, babNumber: 2, startHadith: 2240, endHadith: 2243, title: 'নির্দিষ্ট ওজনে অগ্রিম বেচা-কেনা।', arabic: ''),
    BukhariBab(bookNumber: 35, babNumber: 3, startHadith: 2244, endHadith: 2246, title: 'এমন ব্যক্তির নিকটে আগাম মূল্য প্রদান করা যার কাছে মূল বস্তু নেই।', arabic: ''),
    BukhariBab(bookNumber: 35, babNumber: 4, startHadith: 2247, endHadith: 2250, title: 'খেজুরে অগ্রিম বেচা-কেনা।', arabic: ''),
    BukhariBab(bookNumber: 35, babNumber: 5, startHadith: 2251, endHadith: 2251, title: 'আগাম বেচা-কেনায় জামিন নিযুক্ত করা।', arabic: ''),
    BukhariBab(bookNumber: 35, babNumber: 6, startHadith: 2252, endHadith: 2252, title: 'অগ্রিম বেচা-কেনায় বন্ধক রাখা।', arabic: ''),
    BukhariBab(bookNumber: 35, babNumber: 7, startHadith: 2253, endHadith: 2255, title: 'নির্দিষ্ট মেয়াদে অগ্রিম বেচা-কেনা।', arabic: ''),
    BukhariBab(bookNumber: 35, babNumber: 8, startHadith: 2256, endHadith: 2256, title: 'উটনীর বাচ্চা প্রসবের মেয়াদে অগ্রিম বেচা-কেনা।', arabic: ''),
BukhariBab(bookNumber: 36, babNumber: 1, startHadith: 2257, endHadith: 2257, title: 'স্থাবর অস্থাবর সম্পত্তিতে শুফ‘আহ এর অধিকার। যখন (ভাগ-বাঁটোয়ারা হয়ে) সীমানা নির্ধারিত হয়ে যায়, তখন আর শুফ‘আহ এর অধিকার থাকে না।', arabic: ''),
BukhariBab(bookNumber: 36, babNumber: 2, startHadith: 2258, endHadith: 2258, title: 'বিক্রয়ের আগে শুফ্‘আ এর অধিকারীর কাছে (বিক্রয়ের) প্রস্তাব করা।', arabic: ''),
BukhariBab(bookNumber: 36, babNumber: 3, startHadith: 2259, endHadith: 2259, title: 'অধ্যায় : কোন্ প্রতিবেশী অধিক নিকটবর্তী।', arabic: ''),
BukhariBab(bookNumber: 37, babNumber: 1, startHadith: 2260, endHadith: 2261, title: 'সৎ ব্যক্তিকে শ্রমিক হিসেবে নিয়োগ প্রদান।', arabic: ''),
BukhariBab(bookNumber: 37, babNumber: 2, startHadith: 2262, endHadith: 2262, title: 'কয়েক কিরাআতের বদলে ছাগল-ভেড়া চরানো।', arabic: ''),
BukhariBab(bookNumber: 37, babNumber: 3, startHadith: 2263, endHadith: 2263, title: 'প্রয়োজনবোধে অথবা কোন মুসলিম পাওয়া না গেলে মুশরিকদের শ্রমিক নিয়োগ করা।', arabic: ''),
BukhariBab(bookNumber: 37, babNumber: 4, startHadith: 2264, endHadith: 2264, title: 'যদি কোন ব্যক্তি এ শর্তে কোন শ্রমিক নিয়োগ করে যে, সে তিন দিন অথবা এক মাস অথবা এক বছর পর কাজ করে দেবে, তবে তা বৈধ। তখন নির্ধারিত সময় আসলে উভয়েই তাদের নির্দিষ্ট শর্তাবলীর উপর বহাল থাকবে।', arabic: ''),
BukhariBab(bookNumber: 37, babNumber: 5, startHadith: 2265, endHadith: 2266, title: 'জিহাদের ময়দানে মজদুর নিয়োগ।', arabic: ''),
BukhariBab(bookNumber: 37, babNumber: 7, startHadith: 2267, endHadith: 2267, title: 'পতিত প্রায় কোন দেয়াল খাড়া করে দেয়ার জন্য মজদুর নিয়োগ করা জায়িয।', arabic: ''),
BukhariBab(bookNumber: 37, babNumber: 8, startHadith: 2268, endHadith: 2268, title: 'অর্ধেক দিনের জন্য মজদুর নিয়োগ করা।', arabic: ''),
BukhariBab(bookNumber: 37, babNumber: 9, startHadith: 2269, endHadith: 2269, title: 'আসরের নামাজ পর্যন্ত শ্রমিক নিয়োগ করা।', arabic: ''),
BukhariBab(bookNumber: 37, babNumber: 10, startHadith: 2270, endHadith: 2270, title: 'মজদুরকে পারিশ্রমিক না দেয়ার পাপ।', arabic: ''),
BukhariBab(bookNumber: 37, babNumber: 11, startHadith: 2271, endHadith: 2271, title: 'আসর সময় হতে রাত পর্যন্ত শ্রমিক নিয়োগ করা।', arabic: ''),
BukhariBab(bookNumber: 37, babNumber: 12, startHadith: 2272, endHadith: 2272, title: 'কোন লোককে শ্রমিক নিয়োগ করার পর সে পারিশ্রমিক না নিলে নিয়োগকর্তা সে ব্যক্তির পারিশ্রমিকের টাকা কাজে খাটালো, ফলে তা বৃদ্ধি পেল এবং যে ব্যক্তি অপরের সম্পদ কাজে লাগালো এতে তা বৃদ্ধি পেল।', arabic: ''),
BukhariBab(bookNumber: 37, babNumber: 13, startHadith: 2273, endHadith: 2273, title: 'যে ব্যক্তি নিজেকে পিঠে বোঝা বহনের কাজে নিয়োগ করে প্রাপ্ত পারিশ্রমিক হতে দান-খয়রাত করে এবং বোঝা বহনকারীর মজুরী প্রসঙ্গে।', arabic: ''),
BukhariBab(bookNumber: 37, babNumber: 14, startHadith: 2274, endHadith: 2274, title: 'দালালীর প্রাপ্য প্রসঙ্গে।', arabic: ''),
BukhariBab(bookNumber: 37, babNumber: 15, startHadith: 2275, endHadith: 2275, title: 'অমুসলিম দেশে কোন (মুসলিম) ব্যক্তি নিজেকে দারুল হারবের কোন মুশরিকের শ্রমিক খাটতে পারবে কি ?', arabic: ''),
BukhariBab(bookNumber: 37, babNumber: 16, startHadith: 2276, endHadith: 2276, title: 'কোন আরব গোত্রে সূরা ফাতিহা পড়ে ঝাড়-ফুঁক করার বদলে কিছু দেয়া হলে।', arabic: ''),
BukhariBab(bookNumber: 37, babNumber: 17, startHadith: 2277, endHadith: 2277, title: 'কৃতদাসীর কাছ থেকে মাসুল নির্ধারণ এবং বাঁদীর মাসুলের প্রতি সজাগ দৃষ্টি রাখা।', arabic: ''),
BukhariBab(bookNumber: 37, babNumber: 18, startHadith: 2278, endHadith: 2280, title: 'রক্ত মোক্ষণকারীর উপার্জন।', arabic: ''),
BukhariBab(bookNumber: 37, babNumber: 19, startHadith: 2281, endHadith: 2281, title: 'কোন ব্যক্তির কোন কৃতদাসীর মালিকের সাথে এ মর্মে আবেদন করা- সে যেন তার উপর ধার্যকৃত কর কমিয়ে দেয়।', arabic: ''),
BukhariBab(bookNumber: 37, babNumber: 20, startHadith: 2282, endHadith: 2283, title: 'কৃতদাসী এবং পতিতার উপার্জন।', arabic: ''),
BukhariBab(bookNumber: 37, babNumber: 21, startHadith: 2284, endHadith: 2284, title: 'পশুকে পাল দেয়ার মাশুল।', arabic: ''),
BukhariBab(bookNumber: 37, babNumber: 22, startHadith: 2285, endHadith: 2286, title: 'যদি কোন ব্যক্তি ভূমি ইজারা নেয় এবং তাদের দু’জনের কেউ মৃত্যুবরণ করে।', arabic: ''),
BukhariBab(bookNumber: 38, babNumber: 1, startHadith: 2287, endHadith: 2287, title: 'হাওয়াল (দায় অপসারণ) করা। হাওয়ালা করার পর পুনরায় হাওয়ালাকারীর নিকট দাবী করা যায় কি?', arabic: ''),
BukhariBab(bookNumber: 38, babNumber: 2, startHadith: 2288, endHadith: 2288, title: 'যখন (ঋণ) কোন আমীর ব্যক্তির হাওয়ালা করা হয়, তখন (তা মেনে নেয়ার পর) তার পক্ষে প্রত্যাখ্যান করার ইখতিয়ার নেই।', arabic: ''),
BukhariBab(bookNumber: 38, babNumber: 3, startHadith: 2289, endHadith: 2289, title: 'কারো উপর মৃত ব্যক্তির ঋণের ভার হাওয়ালা করা জায়েয।', arabic: ''),
BukhariBab(bookNumber: 39, babNumber: 1, startHadith: 2290, endHadith: 2291, title: 'দেনা ও কর্জের ব্যাপারে দেহ এবং অন্য কিছুর আর্থিক দায় প্রসঙ্গে।', arabic: ''),
BukhariBab(bookNumber: 39, babNumber: 2, startHadith: 2292, endHadith: 2294, title: 'আল্লাহ তা‘আলার বাণীঃ ‘‘যাদের সঙ্গে তোমরা প্রতিশ্রতিবদ্ধ তাদেরকে তাদের অংশ দিয়ে দিবে।’’ (আন-নিসাঃ ৩৩)', arabic: ''),
BukhariBab(bookNumber: 39, babNumber: 3, startHadith: 2295, endHadith: 2296, title: 'যদি কোন ব্যক্তি কোন মৃত ব্যক্তির দেনার দায় গ্রহণ করে, তবে তার এ দায়িত্ব এড়িয়ে যাবার ইখতিয়ার নেই।', arabic: ''),
BukhariBab(bookNumber: 39, babNumber: 4, startHadith: 2297, endHadith: 2297, title: 'নাবী (সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম)-এর যামানায় আবূ বাকার সিদ্দীক (রাঃ) কর্তৃক (মুশরিকদের) নিরাপত্তা দান এবং তার অঙ্গীকারাবদ্ধ হওয়ার বর্ণনা।', arabic: ''),
BukhariBab(bookNumber: 39, babNumber: 5, startHadith: 2298, endHadith: 2298, title: 'ঋণ', arabic: ''),
BukhariBab(bookNumber: 40, babNumber: 1, startHadith: 2299, endHadith: 2300, title: 'ভাগ বাঁটোয়ারা ইত্যাদির ক্ষেত্রে এক শরীক অন্য শরীকের ওয়াকিল হওয়া।', arabic: ''),
BukhariBab(bookNumber: 40, babNumber: 2, startHadith: 2301, endHadith: 2301, title: 'মুসলিমের পক্ষে কোন মুসলিমকে মুসলিম দেশে কিংবা অমুসলিম দেশে প্রতিনিধি নিয়োগ করা বৈধ।', arabic: ''),
BukhariBab(bookNumber: 40, babNumber: 3, startHadith: 2302, endHadith: 2303, title: 'স্বর্ণ-রৌপ্য বেচা-কেনা ও ওজনে বিক্রয়যোগ্য বস্তুসমূহে প্রতিনিধি নিয়োগ করা।', arabic: ''),
BukhariBab(bookNumber: 40, babNumber: 4, startHadith: 2304, endHadith: 2304, title: 'রাখাল অথবা প্রতিনিধি কোন বকরী মারা যাচ্ছে বা কোন জিনিস নষ্ট হওয়ার আশঙ্কা দেখলে ব্যবস্থা করা।', arabic: ''),
BukhariBab(bookNumber: 40, babNumber: 5, startHadith: 2305, endHadith: 2305, title: 'উপস্থিত ও অনুপস্থিত ব্যক্তিকে ওয়াকীল নিয়োগ করা বৈধ।', arabic: ''),
BukhariBab(bookNumber: 40, babNumber: 6, startHadith: 2306, endHadith: 2306, title: 'ঋণ পরিশোধ করার জন্য প্রতিনিধি নিয়োগ।', arabic: ''),
BukhariBab(bookNumber: 40, babNumber: 7, startHadith: 2307, endHadith: 2308, title: 'কোন প্রতিনিধিকে কিংবা কোন কওমের সুপারিশকারীকে কোন দ্রব্য হিবা করা বৈধ।', arabic: ''),
BukhariBab(bookNumber: 40, babNumber: 8, startHadith: 2309, endHadith: 2309, title: 'কেউ কোন লোককে কিছু দান করার জন্য প্রতিনিধি নিয়োগ করে, কিন্তু কত দিবে তা উল্লেখ করেনি, তবে সে নিয়ম অনুযায়ী দান করবে।', arabic: ''),
BukhariBab(bookNumber: 40, babNumber: 9, startHadith: 2310, endHadith: 2310, title: 'নারী কর্তৃক বিয়ের ক্ষেত্রে ইমামকে কাফিল নিয়োগ করা।', arabic: ''),
BukhariBab(bookNumber: 40, babNumber: 10, startHadith: 2311, endHadith: 2311, title: 'প্রতিনিধি কোন কিছু বাদ দিলে এবং প্রতিনিধি নিয়োগকারী তা অনুমোদন করলে তা বৈধ; নির্দিষ্ট মেয়াদে ধার প্রদানও বৈধ।', arabic: ''),
BukhariBab(bookNumber: 40, babNumber: 11, startHadith: 2312, endHadith: 2312, title: 'যদি ওয়াকীল কোন খারাপ জিনিস বিক্রয় করে, তবে তার বিক্রয় গ্রহণযোগ্য নয়।', arabic: ''),
BukhariBab(bookNumber: 40, babNumber: 12, startHadith: 2313, endHadith: 2313, title: 'ওয়াক্ফকৃত সম্পদে প্রতিনিধি নিয়োগ ও তার খরচপত্র এবং বন্ধু-বান্ধবকে আহার করানো।', arabic: ''),
BukhariBab(bookNumber: 40, babNumber: 13, startHadith: 2314, endHadith: 2316, title: 'শরী‘আত নির্ধারিত শাস্তি দন্ড প্রয়োগের জন্য প্রতিনিধি নিয়োগ করা।', arabic: ''),
BukhariBab(bookNumber: 40, babNumber: 14, startHadith: 2317, endHadith: 2317, title: 'কুরবানীর উট ও তার রক্ষণাবেক্ষণের জন্য প্রতিনিধি নিয়োগ।', arabic: ''),
BukhariBab(bookNumber: 40, babNumber: 15, startHadith: 2318, endHadith: 2318, title: 'প্রতিনিধিকে বলা হলো, এ মাল আপনি যেখানে ভাল মনে করেন খরচ করেন।', arabic: ''),
BukhariBab(bookNumber: 40, babNumber: 16, startHadith: 2319, endHadith: 2319, title: 'কোষাগার ইত্যাদিতে বিশ্বস্ত প্রতিনিধি নিয়োগ করা।', arabic: ''),
