BukhariBab(bookNumber: 41, babNumber: 13, startHadith: 2333, endHadith: 2333, title: 'যদি কেউ অন্যদের সম্পদ দিয়ে তাদের অনুমতি ব্যতিরেকে কৃষি কাজ করে এবং তাতে তাদের কল্যাণ নিহিত থাকে তবে তা বৈধ।', arabic: ''),
BukhariBab(bookNumber: 41, babNumber: 14, startHadith: 2334, endHadith: 2334, title: 'নাবী (সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম)-এর সাহাবীগণের ওয়াক্ফ ও খাজনার জমি এবং তাঁদের কৃষিকাজ ও লেনদেন প্রসঙ্গে।', arabic: ''),
BukhariBab(bookNumber: 41, babNumber: 15, startHadith: 2335, endHadith: 2335, title: 'যে ব্যক্তি অনাবাদী জমি চাষ করে।', arabic: ''),
BukhariBab(bookNumber: 41, babNumber: 16, startHadith: 2336, endHadith: 2337, title: 'পরিচ্ছেদ নাই।', arabic: ''),
BukhariBab(bookNumber: 41, babNumber: 17, startHadith: 2338, endHadith: 2338, title: 'জমির মালিক বলল, আমি তোমাকে ততদিনের জন্য অবস্থান করতে দেব যতদিন আল্লাহ তা‘আলা তোমাকে অবস্থান করতে দেন এবং কোন নির্দিষ্ট সময়ের উল্লেখ করল না। এমতাবস্থায় তারা একসাথে যতদিন রাযি থাকে ততদিন-এ চুক্তি বলবৎ থাকবে।', arabic: ''),
BukhariBab(bookNumber: 41, babNumber: 18, startHadith: 2339, endHadith: 2345, title: 'নাবী (সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম)-এর সাহাবীগণ (রাঃ) কৃষিকাজ ও ফল-ফসল উৎপাদনে একে অপরকে সহয়তা করতেন তার বিবরণ।', arabic: ''),
