BukhariBab(bookNumber: 43, babNumber: 12, startHadith: 2400, endHadith: 2400, title: 'ধনী ব্যক্তির (ঋণ আদায়ে) গড়িমসি করা অত্যাচারের শামিল।', arabic: ''),
