BukhariBab(bookNumber: 43, babNumber: 16, startHadith: 2403, endHadith: 2403, title: 'গরীব বা অভাবী ব্যক্তির সম্পত্তি বিক্রয় করে তা পাওনাদারদের মধ্যে বন্টন করে দেয়া অথবা তার নিজের খরচের জন্য দিয়ে দেয়া।', arabic: ''),
