BukhariBab(bookNumber: 43, babNumber: 18, startHadith: 2405, endHadith: 2406, title: 'ঋণভার কমানোর সুপারিশ।', arabic: ''),
BukhariBab(bookNumber: 43, babNumber: 19, startHadith: 2407, endHadith: 2408, title: 'ধন-সম্পত্তি অপচয় করা নিষিদ্ধ।', arabic: ''),
BukhariBab(bookNumber: 43, babNumber: 20, startHadith: 2409, endHadith: 2409, title: 'কৃতদাস তার মনিবের সম্পত্তির রক্ষক। সে তার মনিবের আদেশ ছাড়া তা ব্যয় করবে না।', arabic: ''),
BukhariBab(bookNumber: 44, babNumber: 1, startHadith: 2410, endHadith: 2413, title: 'ঋণগ্রস্তকে স্থানান্তরিত করা এবং মুসলিম ও ইয়াহূদীর মধ্যকার ঝগড়ার আপোষ।', arabic: ''),
BukhariBab(bookNumber: 44, babNumber: 3, startHadith: 2414, endHadith: 2415, title: 'যে ব্যক্তি কোন নির্বোধ বা এ ধরনের কোন লোকের সম্পত্তি বিক্রি করে এবং বিক্রি মূল্য তাকে দিয়ে দেয় ও তাকে তার অবস্থার উন্নতি ও অর্থকে যথাযথ ব্যবহার করতে নির্দেশ দেয়। এরপর যদি সে তার অর্থ নষ্ট করে দেয় তাহলে সে তাকে অর্থ ব্যবহার করা হতে বিরত রাখবে।', arabic: ''),
BukhariBab(bookNumber: 44, babNumber: 4, startHadith: 2416, endHadith: 2419, title: 'বিবদমানদের পরস্পরের আলাপ-আলোচনা সম্পর্কে।', arabic: ''),
BukhariBab(bookNumber: 44, babNumber: 5, startHadith: 2420, endHadith: 2420, title: 'পাপে ও বিবাদে লিপ্ত লোকদের অবস্থা অবগত হওয়ার পর তাদেরকে ঘর হতে বহিষ্কার করা।', arabic: ''),
BukhariBab(bookNumber: 44, babNumber: 6, startHadith: 2421, endHadith: 2421, title: 'মৃত ব্যক্তির ওসীয়াতের দাবী।', arabic: ''),
BukhariBab(bookNumber: 44, babNumber: 7, startHadith: 2422, endHadith: 2422, title: 'কারো দ্বারা ক্ষতির আশঙ্কা থাকলে তাকে বন্দী করা।', arabic: ''),
BukhariBab(bookNumber: 44, babNumber: 8, startHadith: 2423, endHadith: 2423, title: 'হারম শরীফে (কাউকে) বেঁধে রাখা এবং বন্দী করা।', arabic: ''),
BukhariBab(bookNumber: 44, babNumber: 9, startHadith: 2424, endHadith: 2424, title: 'পাওনা আদায়ের জন্য (ঋণদাতা ঋণী ব্যক্তির) পিছনে লেগে থাকা।', arabic: ''),
BukhariBab(bookNumber: 44, babNumber: 10, startHadith: 2425, endHadith: 2425, title: 'ঋণের পরিশোধের জন্য তাগাদা করা।', arabic: ''),
BukhariBab(bookNumber: 45, babNumber: 1, startHadith: 2426, endHadith: 2426, title: 'পড়ে থাকা জিনিসের মালিক এসে আলামতের বর্ণনা দিলে তাকে তা ফিরিয়ে দিবে।', arabic: ''),
BukhariBab(bookNumber: 45, babNumber: 2, startHadith: 2427, endHadith: 2427, title: 'হারিয়ে যাওয়া উষ্ট্র।', arabic: ''),
BukhariBab(bookNumber: 45, babNumber: 3, startHadith: 2428, endHadith: 2428, title: 'হারিয়ে যাওয়া ছাগল।', arabic: ''),
BukhariBab(bookNumber: 45, babNumber: 4, startHadith: 2429, endHadith: 2429, title: 'এক বছরের মধ্যে যদি পড়ে থাকা জিনিসের মালিকের দেখা পাওয়া না যায় তবে সেটা যে পেয়েছে তারই হবে।', arabic: ''),
BukhariBab(bookNumber: 45, babNumber: 5, startHadith: 2430, endHadith: 2430, title: 'নদীতে শুকনা কাষ্ঠখন্ড বা চাবুক অথবা এ জাতীয় কোন কিছু পাওয়া গেলে।', arabic: ''),
BukhariBab(bookNumber: 45, babNumber: 6, startHadith: 2431, endHadith: 2432, title: 'রাস্তায় খেজুর পাওয়া গেলে।', arabic: ''),
BukhariBab(bookNumber: 45, babNumber: 7, startHadith: 2433, endHadith: 2434, title: 'মক্কাবাসীদের পড়ে থাকা জিনিসের ঘোষণা কিভাবে দেয়া হবে।', arabic: ''),
BukhariBab(bookNumber: 45, babNumber: 8, startHadith: 2435, endHadith: 2435, title: 'অনুমতি ছাড়া কারো পশু দোহন করবে না।', arabic: ''),
BukhariBab(bookNumber: 45, babNumber: 9, startHadith: 2436, endHadith: 2436, title: 'পড়ে থাকা জিনিসের মালিক এক বছর পরে ফিরে আসলে তার জিনিস তাকে ফিরিয়ে দিবে। কারণ সেটা তার কাছে আমানত ছিল।', arabic: ''),
BukhariBab(bookNumber: 45, babNumber: 10, startHadith: 2437, endHadith: 2437, title: 'পড়ে থাকা জিনিস যাতে খারাপ না হয় এবং কোন অবাঞ্ছিত ব্যক্তি যাতে তুলে না নেয় সে জন্য তা তুলে নিবে কি?', arabic: ''),
BukhariBab(bookNumber: 45, babNumber: 11, startHadith: 2438, endHadith: 2438, title: 'যে ব্যক্তি পড়ে থাকা জিনিসের ঘোষণা করেছে বটে, কিন্তু তা সরকারের কাছে অর্পণ করেনি।', arabic: ''),
BukhariBab(bookNumber: 45, babNumber: 12, startHadith: 2439, endHadith: 2439, title: 'পরিচ্ছেদ নাই।', arabic: ''),
BukhariBab(bookNumber: 46, babNumber: 1, startHadith: 2440, endHadith: 2440, title: 'অপরাধের শাস্তি।', arabic: ''),
BukhariBab(bookNumber: 46, babNumber: 2, startHadith: 2441, endHadith: 2441, title: 'আল্লাহ তা‘আলার বাণীঃ সাবধান! যালিমদের উপর আল্লাহর অভিশাপ।', arabic: ''),
BukhariBab(bookNumber: 46, babNumber: 3, startHadith: 2442, endHadith: 2442, title: 'মুসলিম মুসলিমের প্রতি অত্যাচার করবে না এবং তাকে অপমানিতও করবে না।', arabic: ''),
BukhariBab(bookNumber: 46, babNumber: 4, startHadith: 2443, endHadith: 2444, title: 'তোমার ভাইকে সাহায্য কর, সে অত্যাচারী হোক বা অত্যাচারিত।', arabic: ''),
BukhariBab(bookNumber: 46, babNumber: 5, startHadith: 2445, endHadith: 2446, title: 'অত্যাচারিতকে সাহায্য করা।', arabic: ''),
BukhariBab(bookNumber: 46, babNumber: 8, startHadith: 2447, endHadith: 2447, title: 'জুলুম কিয়ামতের দিন গাঢ় অন্ধকার রূপ ধারণ করবে।', arabic: ''),
BukhariBab(bookNumber: 46, babNumber: 9, startHadith: 2448, endHadith: 2448, title: 'মাযলুমের বদ-দোয়াকে ভয় করা এবং তা হতে বেঁচে থাকা।', arabic: ''),
BukhariBab(bookNumber: 46, babNumber: 10, startHadith: 2449, endHadith: 2449, title: 'কেউ কারো উপর যুলুম করে এবং মাযলুম ব্যক্তি তাকে ক্ষমা করে দেয় এর পরও সে অত্যাচারের কথা প্রকাশ করতে পারবে কি?', arabic: ''),
BukhariBab(bookNumber: 46, babNumber: 11, startHadith: 2450, endHadith: 2450, title: 'যদি কেউ কারো জুলুম বা অন্যায় মাফ করে দেয়, তবে সে জুলুমের জন্য পুনরায় তাকে দোষী সাব্যস্ত করা চলবে না।', arabic: ''),
BukhariBab(bookNumber: 46, babNumber: 12, startHadith: 2451, endHadith: 2451, title: 'যদি কোন ব্যক্তি কাউকে কোন বিষয়ে অনুমতি প্রদান করে, তাকে মাফ করে, কিন্তু কী পরিমাণ ক্ষমা করল কিংবা কতটুকুর জন্য অনুমতি প্রদান করল তা উল্লেখ না করে।', arabic: ''),
BukhariBab(bookNumber: 46, babNumber: 13, startHadith: 2452, endHadith: 2454, title: 'কোন ব্যক্তি কারো জমির কিছু অংশ ছিনিয়ে নেয় অথবা জুলুম করে নিয়ে নেয় তার গুনাহ।', arabic: ''),
BukhariBab(bookNumber: 46, babNumber: 14, startHadith: 2455, endHadith: 2456, title: 'যদি কোন ব্যক্তি কাউকে কোন বিষয়ে অনুমতি প্রদান করে তবে তা বৈধ।', arabic: ''),
BukhariBab(bookNumber: 46, babNumber: 15, startHadith: 2457, endHadith: 2457, title: 'মহান আল্লাহর বাণীঃ প্রকৃতপক্ষে সে ঘোর বিরোধী। (আল-বাকারাঃ ২০৪)', arabic: ''),
BukhariBab(bookNumber: 46, babNumber: 16, startHadith: 2458, endHadith: 2458, title: 'যে ব্যক্তি জেনে শুনে অন্যায় বিষয়ে বিবাদ করে, তার গুনাহ।', arabic: ''),
BukhariBab(bookNumber: 46, babNumber: 17, startHadith: 2459, endHadith: 2459, title: 'ঝগড়া বিবাদ করার সময় অশ্লীল ভাষা প্রয়োগ।', arabic: ''),
BukhariBab(bookNumber: 46, babNumber: 18, startHadith: 2460, endHadith: 2461, title: 'অত্যাচারীর সম্পদ যদি অত্যাচারিতের হস্তগত হয়, তবে তা হতে সে নিজের প্রতিশোধ গ্রহণ করতে পারে।', arabic: ''),
BukhariBab(bookNumber: 46, babNumber: 19, startHadith: 2462, endHadith: 2462, title: 'ছায়াযুক্ত স্থান সম্পর্কে।', arabic: ''),
BukhariBab(bookNumber: 46, babNumber: 20, startHadith: 2463, endHadith: 2463, title: 'কোন প্রতিবেশী যেন তার প্রতিবেশীকে তার দেয়ালে খুঁটি লাগাতে নিষেধ না করে।', arabic: ''),
BukhariBab(bookNumber: 46, babNumber: 21, startHadith: 2464, endHadith: 2464, title: 'রাস্তায় মদ বহিয়ে দেয়া।', arabic: ''),
BukhariBab(bookNumber: 46, babNumber: 22, startHadith: 2465, endHadith: 2465, title: 'ঘরের আঙিনা এবং সেখানে রাস্তায় বসা।', arabic: ''),
BukhariBab(bookNumber: 46, babNumber: 23, startHadith: 2466, endHadith: 2466, title: 'রাস্তায় কূপ খনন করা, যদি তা যাতায়াতকারীদের কারো কষ্টের কারণ না হয়।', arabic: ''),
BukhariBab(bookNumber: 46, babNumber: 25, startHadith: 2467, endHadith: 2469, title: 'দালানের ছাদে বা অন্য কোথাও উঁচু বা নীচু চিলেকোঠা ও কক্ষ নির্মাণ করা।', arabic: ''),
BukhariBab(bookNumber: 46, babNumber: 26, startHadith: 2470, endHadith: 2470, title: 'যে ব্যক্তি তার উট মসজিদের উঠানে কিংবা দরজায় বেঁধে রাখে।', arabic: ''),
BukhariBab(bookNumber: 46, babNumber: 27, startHadith: 2471, endHadith: 2471, title: 'লোকজনের আবর্জনা নিক্ষেপের জায়গায় দাঁড়ানো ও পেশাব করা।', arabic: ''),
BukhariBab(bookNumber: 46, babNumber: 28, startHadith: 2472, endHadith: 2472, title: 'যে ব্যক্তি ডালপালা ও কষ্টদায়ক দ্রব্য রাস্তা থেকে তুলে দূরে নিক্ষেপ করে।', arabic: ''),
BukhariBab(bookNumber: 46, babNumber: 29, startHadith: 2473, endHadith: 2473, title: 'যদি ইজমালি পতিত জমিতে রাস্তার ব্যাপারে লোকেদের মাঝে মতবিরোধ দেখা দেয় এবং কোন শরীক সেখানে বাড়ী তৈরী করতে চায় তবে রাস্তার জন্য তা হতে সাত হাত জমি রেখে দিতে হবে।', arabic: ''),
BukhariBab(bookNumber: 46, babNumber: 30, startHadith: 2474, endHadith: 2475, title: 'মালিকের অনুমতি ব্যতীত লুটপাট করা।', arabic: ''),
BukhariBab(bookNumber: 46, babNumber: 31, startHadith: 2476, endHadith: 2476, title: 'ক্রুশ ভেঙ্গে ফেলা এবং শূকর হত্যা করা।', arabic: ''),
BukhariBab(bookNumber: 46, babNumber: 32, startHadith: 2477, endHadith: 2479, title: 'মদের (মৃৎপাত্র) মটকা ভেঙ্গে ফেলা অথবা মশক ছিদ্র করা যায় কি? যদি কেউ নিজের লাঠি দ্বারা মুর্তি বা ক্রুশ অথবা তবলা অথবা কোন অপ্রয়োজনীয় বস্তু ভেঙ্গে ফেলে (তবে তার হুকুম কী)?', arabic: ''),
BukhariBab(bookNumber: 46, babNumber: 33, startHadith: 2480, endHadith: 2480, title: 'সম্পদ হিফাযাত করতে গিয়ে যে ব্যক্তি নিহত হয়।', arabic: ''),
BukhariBab(bookNumber: 46, babNumber: 34, startHadith: 2481, endHadith: 2481, title: 'যদি কেউ অন্য কারো পাত্র বা কোন বস্তু ভেঙ্গে ফেলে।', arabic: ''),
BukhariBab(bookNumber: 47, babNumber: 1, startHadith: 2483, endHadith: 2486, title: 'খাদ্য, পাথেয় এবং দ্রব্য সামগ্রীতে অংশ গ্রহণ।', arabic: ''),
BukhariBab(bookNumber: 47, babNumber: 2, startHadith: 2487, endHadith: 2487, title: 'কোন জিনিসের দুই জন অংশীদার থাকলে তারা যাকাত দানের পর তা আনুপাতিক হারে ভাগ করে নিবে।', arabic: ''),
BukhariBab(bookNumber: 47, babNumber: 3, startHadith: 2488, endHadith: 2488, title: 'ছাগল ও ভেড়া ভাগ করা।', arabic: ''),
BukhariBab(bookNumber: 47, babNumber: 4, startHadith: 2489, endHadith: 2490, title: 'এক সাথে খেতে বসলে সাথীর অনুমতি ছাড়া এক সাথে দু‘টো করে খেজুর ভক্ষণ করা (নিষিদ্ধ)।', arabic: ''),
BukhariBab(bookNumber: 47, babNumber: 5, startHadith: 2491, endHadith: 2492, title: 'শরীকদের মাঝে এজমালি দ্রব্যে উচিত দাম নির্ধারণ সম্পর্কে।', arabic: ''),
BukhariBab(bookNumber: 47, babNumber: 6, startHadith: 2493, endHadith: 2493, title: 'লটারির মাধ্যমে অংশ নিরূপণ ও ভাগ করা যাবে কিনা?', arabic: ''),
BukhariBab(bookNumber: 47, babNumber: 7, startHadith: 2494, endHadith: 2494, title: 'ইয়াতিম ও উত্তরাধিকারীদের অংশীদারিত্ব।', arabic: ''),
BukhariBab(bookNumber: 47, babNumber: 8, startHadith: 2495, endHadith: 2495, title: 'জমি (বাড়ী বাগান) ইত্যাদিতে অংশীদারিত্ব।', arabic: ''),
BukhariBab(bookNumber: 47, babNumber: 9, startHadith: 2496, endHadith: 2496, title: 'যদি অংশীদাররা ঘর, বাগান ইত্যাদি ভাগ করে নেয় তবে পুনরায় একত্রিত করার এবং শুফ‘আহ্ দাবি করার হক তাদের থাকে না।', arabic: ''),
BukhariBab(bookNumber: 47, babNumber: 10, startHadith: 2497, endHadith: 2498, title: 'স্বর্ণ-রৌপ্য ও নগদ আদান প্রদানের বস্তুতে অংশীদারিত্ব।', arabic: ''),
BukhariBab(bookNumber: 47, babNumber: 11, startHadith: 2499, endHadith: 2499, title: 'ভাগচাষে যিম্মী ও মুশরিকদের অংশীদার করা।', arabic: ''),
BukhariBab(bookNumber: 47, babNumber: 12, startHadith: 2500, endHadith: 2500, title: 'ছাগল ভেড়ার ইনসাফের ভিত্তিতে ভাগ করা।', arabic: ''),
BukhariBab(bookNumber: 47, babNumber: 13, startHadith: 2501, endHadith: 2502, title: 'খাদ্য-দ্রব্য প্রভৃতিতে অংশীদারিত্ব।', arabic: ''),
BukhariBab(bookNumber: 47, babNumber: 14, startHadith: 2503, endHadith: 2504, title: 'কৃতদাস দাসীতে অংশীদারিত্ব।', arabic: ''),
BukhariBab(bookNumber: 47, babNumber: 15, startHadith: 2505, endHadith: 2506, title: 'কুরবানীর জানোয়ার ও উটে অংশগ্রহণ।', arabic: ''),
BukhariBab(bookNumber: 47, babNumber: 16, startHadith: 2507, endHadith: 2507, title: 'যে ব্যক্তি ভাগ করার সময় দশটি বকরীকে একটা উটের সমান মনে করে।', arabic: ''),
BukhariBab(bookNumber: 48, babNumber: 1, startHadith: 2508, endHadith: 2508, title: 'স্থায়ী বাসস্থানে থাকা অবস্থায় বন্ধক রাখা।', arabic: ''),
BukhariBab(bookNumber: 48, babNumber: 2, startHadith: 2509, endHadith: 2509, title: 'যে ব্যক্তি নিজ বর্ম বন্ধক রাখে।', arabic: ''),
BukhariBab(bookNumber: 48, babNumber: 3, startHadith: 2510, endHadith: 2510, title: 'অস্ত্র বন্ধক রাখা।', arabic: ''),
BukhariBab(bookNumber: 48, babNumber: 4, startHadith: 2511, endHadith: 2512, title: 'বন্ধক রাখা জন্তুর উপর চড়া যায় এবং দুধ দোহন করা যায়।', arabic: ''),
BukhariBab(bookNumber: 48, babNumber: 5, startHadith: 2513, endHadith: 2513, title: 'ইয়াহূদী ও অন্যান্যদের (অমুসলিমের) নিকট বন্ধক রাখা।', arabic: ''),
BukhariBab(bookNumber: 48, babNumber: 6, startHadith: 2514, endHadith: 2516, title: 'বন্ধকদাতা ও বন্ধক গ্রহীতার মাঝে বিরোধ দেখা দিলে বা অনুরূপ কোন কিছু হলে বাদীর দায়িত্ব সাক্ষী পেশ করা আর বিবাদীর দায়িত্ব শপথ করা।', arabic: ''),
BukhariBab(bookNumber: 49, babNumber: 1, startHadith: 2517, endHadith: 2517, title: 'ক্রীতদাস আযাদ করা ও তার গুরুত্ব।', arabic: ''),
BukhariBab(bookNumber: 49, babNumber: 2, startHadith: 2518, endHadith: 2518, title: 'কোন্ ধরনের ক্রীতদাস আযাদ করা শ্রেয়?', arabic: ''),
BukhariBab(bookNumber: 49, babNumber: 3, startHadith: 2519, endHadith: 2520, title: 'সূর্যগ্রহণ ও (আল্লাহর কুদরতের) বিভিন্ন নিদর্শন প্রকাশের সময় ক্রীতদাস আযাদ করা পছন্দনীয়।', arabic: ''),
BukhariBab(bookNumber: 49, babNumber: 4, startHadith: 2521, endHadith: 2525, title: 'দু’ ব্যক্তির মালিকানাভুক্ত ক্রীতদাস বা কয়েকজন অংশীদারের দাসী আযাদ করা।', arabic: ''),
BukhariBab(bookNumber: 49, babNumber: 5, startHadith: 2526, endHadith: 2527, title: 'কেউ ক্রীতদাসের নিজের অংশ আযাদ করে দিলে এবং তার জরুরী অর্থ না থাকলে চুক্তিবদ্ধ ক্রীতদাসের মতো তাকে অতিরিক্ত ক্লেশ না দিয়ে আয় করতে বলা হবে।', arabic: ''),
BukhariBab(bookNumber: 49, babNumber: 6, startHadith: 2528, endHadith: 2529, title: 'ভুলক্রমে অথবা অনিচ্ছায় ক্রীতদাস আযাদ করা ও স্ত্রীকে তালাক দেয়া ইত্যাদি। আল্লাহ তা‘আলার সন্তোষ ব্যতীত অন্য কোন উদ্দেশে গোলাম আযাদ করা যায় না।', arabic: ''),
BukhariBab(bookNumber: 49, babNumber: 7, startHadith: 2530, endHadith: 2532, title: 'আযাদ করার সংকল্পে কোন ব্যক্তি নিজের ক্রীতদাস সম্পর্কে ‘সে আল্লাহর জন্য নির্দিষ্ট’ বলা এবং আযাদ করার ক্ষেত্রে সাক্ষী রাখা।', arabic: ''),
BukhariBab(bookNumber: 49, babNumber: 8, startHadith: 2533, endHadith: 2533, title: 'উম্মু ওয়ালাদ সম্পর্কে।', arabic: ''),
BukhariBab(bookNumber: 49, babNumber: 9, startHadith: 2534, endHadith: 2534, title: 'মুদাববার (ক্রীতদাস) বিক্রয় করা।', arabic: ''),
BukhariBab(bookNumber: 49, babNumber: 10, startHadith: 2535, endHadith: 2536, title: 'ক্রীতদাসের অভিভাবকত্ব বিক্রয় বা দান করা।', arabic: ''),
BukhariBab(bookNumber: 49, babNumber: 11, startHadith: 2537, endHadith: 2537, title: 'কোন ব্যক্তির মুশরিক ভাই বা চাচা যুদ্ধে বন্দী হলে কি তাদের পক্ষ হতে মুক্তিপণ গ্রহণ করা হবে?', arabic: ''),
BukhariBab(bookNumber: 49, babNumber: 12, startHadith: 2538, endHadith: 2538, title: 'মুশরিক কর্তৃক গোলাম আযাদ করা।', arabic: ''),
BukhariBab(bookNumber: 49, babNumber: 13, startHadith: 2539, endHadith: 2543, title: 'কোন আরব যদি কোন দাস-দাসীর মালিক হয় এবং তাকে দান করে, বিক্রয় করে, সহবাস করে এবং ফিদিয়া হিসাবে দেয় অথবা শিশুদেরকে বন্দী করে রাখে তবে এর বিধান কী?', arabic: ''),
BukhariBab(bookNumber: 49, babNumber: 14, startHadith: 2544, endHadith: 2544, title: 'নিজ গোলামকে জ্ঞান ও আদব কায়দা শিক্ষা দেয়ার গুরুত্ব।', arabic: ''),
BukhariBab(bookNumber: 49, babNumber: 15, startHadith: 2545, endHadith: 2545, title: 'নাবী (সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম)-এর বাণী, তোমাদের গোলামেরা তোমাদেরই ভাই। কাজেই তোমরা যা খাবে তা হতে তাদেরকেও খাওয়াবে।', arabic: ''),
BukhariBab(bookNumber: 49, babNumber: 16, startHadith: 2546, endHadith: 2549, title: 'যে ক্রীতদাস উত্তমরূপে তার মহান প্রভুর (আল্লাহর) ইবাদত করে আর তার মালিকের শুভাকাঙ্ক্ষী হয়।', arabic: ''),
BukhariBab(bookNumber: 49, babNumber: 17, startHadith: 2550, endHadith: 2556, title: 'দাসদের মারধোর করা এবং আমার ক্রীতদাস ও আমার বাঁদী এরূপ বলা মাকরূহ।', arabic: ''),
BukhariBab(bookNumber: 49, babNumber: 18, startHadith: 2557, endHadith: 2557, title: 'খাদিম যখন ভালভাবে খাবার পরিবেশন করে।', arabic: ''),
BukhariBab(bookNumber: 49, babNumber: 19, startHadith: 2558, endHadith: 2558, title: 'ক্রীতদাস আপন মালিকের সম্পত্তির হিফাযাতকারী। নাবী (সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম) সম্পত্তিকে মালিকের সঙ্গে সম্পর্কিত করেছেন।', arabic: ''),
BukhariBab(bookNumber: 49, babNumber: 20, startHadith: 2559, endHadith: 2559, title: 'ক্রীতদাসের মুখমণ্ডলে মারবে না।', arabic: ''),
BukhariBab(bookNumber: 50, babNumber: 1, startHadith: 2560, endHadith: 2560, title: 'মুকাতাব বা চুক্তির ভিত্তিতে অর্থের কিস্তি প্রসঙ্গে। প্রতি বছর এক কিস্তি করে আদায় করা।', arabic: ''),
BukhariBab(bookNumber: 50, babNumber: 2, startHadith: 2561, endHadith: 2562, title: 'মুকাতাবের উপর যে সব শর্তারোপ করা বৈধ এবং আল্লাহর কিতাবে নেই এমন শর্তারোপ করা। এ বিষয়ে ইবনু ‘উমার (রাঃ) হতে হাদীস বর্ণিত হয়েছে।', arabic: ''),
BukhariBab(bookNumber: 50, babNumber: 3, startHadith: 2563, endHadith: 2563, title: 'মানুষের নিকট মুকাতাবের সাহায্য চাওয়া ও সাহায্য প্রার্থনা করা।', arabic: ''),
BukhariBab(bookNumber: 50, babNumber: 4, startHadith: 2564, endHadith: 2564, title: 'মুকাতাবের সমর্থন সাপেক্ষে তাকে বিক্রয় করা।', arabic: ''),
BukhariBab(bookNumber: 50, babNumber: 5, startHadith: 2565, endHadith: 2565, title: 'মুকাতাব যদি (কাউকে) বলে, আমাকে ক্রয় করে আযাদ করে দিন, আর সে যদি ঐ উদ্দেশে তাকে খরিদ করে।', arabic: ''),
BukhariBab(bookNumber: 53, babNumber: 1, startHadith: 2690, endHadith: 2691, title: 'মানুষের মধ্যে আপোস-মীমাংসা করে দেয়া।', arabic: ''),
BukhariBab(bookNumber: 53, babNumber: 2, startHadith: 2692, endHadith: 2692, title: 'মানুষের মধ্যে মীমাংসাকারী ব্যক্তি মিথ্যাবাদী নয়।', arabic: ''),
BukhariBab(bookNumber: 53, babNumber: 3, startHadith: 2693, endHadith: 2693, title: 'সঙ্গী-সাথীদের প্রতি ইমামের কথা ‘‘চলো যাই আমরা মীমাংসা করে দেই’’।', arabic: ''),
BukhariBab(bookNumber: 53, babNumber: 4, startHadith: 2694, endHadith: 2694, title: 'মহান আল্লাহর বাণীঃ ‘‘উভয়ে আপোস নিষ্পত্তি করতে চাইলে আপোস নিষ্পত্তিই শ্রেয়।’’ (আন-নিসা ১২৮)', arabic: ''),
BukhariBab(bookNumber: 53, babNumber: 5, startHadith: 2695, endHadith: 2697, title: 'অন্যায়ের উপর সন্ধিবদ্ধ হলে তা বাতিল।', arabic: ''),
BukhariBab(bookNumber: 53, babNumber: 6, startHadith: 2698, endHadith: 2699, title: 'কিভাবে সন্ধিপত্র লেখা হবে? অমুকের পুত্র অমুক এবং অমুকের পুত্র অমুক লিখাতে হবে। গোত্র বা বংশের উল্লেখ না করলেও ক্ষতি নেই।', arabic: ''),
BukhariBab(bookNumber: 53, babNumber: 7, startHadith: 2700, endHadith: 2702, title: 'মুশরিকদের সঙ্গে সন্ধি।', arabic: ''),
BukhariBab(bookNumber: 53, babNumber: 8, startHadith: 2703, endHadith: 2703, title: 'ক্ষতিপূরণের ব্যাপারে সন্ধি।', arabic: ''),
BukhariBab(bookNumber: 53, babNumber: 9, startHadith: 2704, endHadith: 2704, title: 'হাসান ইব্নু ‘আলী (রাঃ) সম্পর্কে নাবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর উক্তিঃ আমার এ ছেলেটি একজন নেতা। সম্ভবত আল্লাহ্ এর মাধ্যমে দু’টি বড় দলের মধ্যে সন্ধি স্থাপন করাবেন।', arabic: ''),
BukhariBab(bookNumber: 53, babNumber: 10, startHadith: 2705, endHadith: 2706, title: 'আপোস মীমাংসার ব্যাপারে ইমাম পরামর্শ দিবেন কি?', arabic: ''),
BukhariBab(bookNumber: 53, babNumber: 11, startHadith: 2707, endHadith: 2707, title: 'মানুষের মধ্যে মীমাংসা এবং ন্যায় বিচার করার ফযীলত।', arabic: ''),
BukhariBab(bookNumber: 53, babNumber: 12, startHadith: 2708, endHadith: 2708, title: 'ইমাম বিবাদ মীমাংসা করে নেয়ার নির্দেশ দেয়ার পরও তা অমান্য করলে তার বিরুদ্ধে যথার্থ হুকুম জারী করতে হবে।', arabic: ''),
BukhariBab(bookNumber: 53, babNumber: 13, startHadith: 2709, endHadith: 2709, title: 'পাওনাদারদের মধ্যে এবং ওয়ারিসদের মধ্যে মীমাংসা করে দেয়া এবং এ ব্যাপারে অনুমান করা।', arabic: ''),
BukhariBab(bookNumber: 53, babNumber: 14, startHadith: 2710, endHadith: 2710, title: 'ঋণ ও নগদ সম্পদের বিনিময়ে আপোস করা।', arabic: ''),
BukhariBab(bookNumber: 54, babNumber: 1, startHadith: 2711, endHadith: 2715, title: 'ইসলামে আহ্কামে ও ক্রয়-বিক্রয়ে যে সব শর্ত জায়িয।', arabic: ''),
BukhariBab(bookNumber: 54, babNumber: 2, startHadith: 2716, endHadith: 2716, title: 'তাবীর করা খেজুর গাছ বিক্রি করা।', arabic: ''),
BukhariBab(bookNumber: 54, babNumber: 3, startHadith: 2717, endHadith: 2717, title: 'বিক্রয়ে শর্তারোপ করা।', arabic: ''),
BukhariBab(bookNumber: 54, babNumber: 4, startHadith: 2718, endHadith: 2718, title: 'নির্দিষ্ট স্থান পর্যন্ত সওয়ারীর পিঠে চড়ে যাবার শর্তে পশু বিক্রি করা জায়িয।', arabic: ''),
BukhariBab(bookNumber: 54, babNumber: 5, startHadith: 2719, endHadith: 2720, title: 'বর্গাচাষ ইত্যাদির বিষয়ে শর্তাবলী।', arabic: ''),
BukhariBab(bookNumber: 54, babNumber: 6, startHadith: 2721, endHadith: 2721, title: 'বিবাহ বন্ধনের সময় মাহর সম্পর্কে শর্তাবলী।', arabic: ''),
BukhariBab(bookNumber: 54, babNumber: 7, startHadith: 2722, endHadith: 2722, title: 'বর্গাচাষের শর্তাবলী।', arabic: ''),
BukhariBab(bookNumber: 54, babNumber: 8, startHadith: 2723, endHadith: 2723, title: 'বিবাহে যে সব শর্ত বৈধ নয়।', arabic: ''),
BukhariBab(bookNumber: 54, babNumber: 9, startHadith: 2724, endHadith: 2725, title: 'দন্ড বিধিতে যে সকল শর্ত বৈধ নয়।', arabic: ''),
BukhariBab(bookNumber: 54, babNumber: 10, startHadith: 2726, endHadith: 2726, title: 'মুক্ত করা হবে এ শর্তে মুকাতাব বিক্রিত হতে রাযী হলে তার জন্য কী কী শর্ত জায়িয।', arabic: ''),
BukhariBab(bookNumber: 54, babNumber: 11, startHadith: 2727, endHadith: 2727, title: 'তালাকের শর্তাবলী।', arabic: ''),
BukhariBab(bookNumber: 54, babNumber: 12, startHadith: 2728, endHadith: 2728, title: 'লোকজনের সাথে মৌখিক শর্ত করা।', arabic: ''),
BukhariBab(bookNumber: 54, babNumber: 13, startHadith: 2729, endHadith: 2729, title: '‘ওয়ালা’র ব্যাপারে অধিকার অর্জনের শর্তারোপ।', arabic: ''),
BukhariBab(bookNumber: 54, babNumber: 14, startHadith: 2730, endHadith: 2730, title: 'বর্গাচাষের ক্ষেত্রে এমন শর্তারোপ করা যে, যখন ইচ্ছা আমি তোমাকে বের করে দিব।', arabic: ''),
BukhariBab(bookNumber: 54, babNumber: 15, startHadith: 2731, endHadith: 2733, title: 'যুদ্ধের প্রতিপক্ষীয়দের সাথে জিহাদ ও সমঝোতার ব্যাপারে শর্তারোপ এবং লোকদের সঙ্গে কৃত মৌখিক শর্ত লিপিবদ্ধ করা।', arabic: ''),
BukhariBab(bookNumber: 54, babNumber: 16, startHadith: 2734, endHadith: 2734, title: 'মুকাতাব প্রসঙ্গে এবং যে সব শর্ত আল্লাহর কিতাবের বিপরীত তা বৈধ নয়।', arabic: ''),
BukhariBab(bookNumber: 54, babNumber: 17, startHadith: 2735, endHadith: 2735, title: 'শর্তারোপ করা ও স্বীকারোক্তির মধ্য থেকে কিছু বাদ দেয়ার বৈধতা এবং লোকদের মধ্যে প্রচলিত শর্তাবলী প্রসঙ্গে যখন কেউ বলে যে, এক বা দু’ ব্যতীত একশ’? (তবে হুকুম কী হবে)।', arabic: ''),
BukhariBab(bookNumber: 54, babNumber: 18, startHadith: 2736, endHadith: 2736, title: 'ওয়াক্ফের ব্যাপারে শর্তাবলী।', arabic: ''),
  BukhariBab(bookNumber: 55, babNumber: 1, startHadith: 2738, endHadith: 2741, title: 'অসীয়াত প্রসঙ্গে', arabic: ''),
  BukhariBab(bookNumber: 55, babNumber: 2, startHadith: 2742, endHadith: 2742, title: 'ওয়ারিসদেরকে অন্যের নিকট হাত পাতা অবস্থায় রেখে যাওয়ার চেয়ে মালদার রেখে যাওয়া উত্তম।', arabic: ''),
  BukhariBab(bookNumber: 55, babNumber: 3, startHadith: 2743, endHadith: 2744, title: 'এক তৃতীয়াংশ অসীয়াত করা প্রসঙ্গে।', arabic: ''),
  BukhariBab(bookNumber: 55, babNumber: 4, startHadith: 2745, endHadith: 2745, title: 'অসীর নিকট অসীয়াতকারীর কথাঃ তুমি আমার সন্তানাদির প্রতি খেয়াল রাখবে, আর অসীর জন্য কেমন দাবী জায়িয।', arabic: ''),
  BukhariBab(bookNumber: 55, babNumber: 5, startHadith: 2746, endHadith: 2746, title: 'রুগ্ন ব্যক্তি মাথা দিয়ে স্পষ্টভাবে ইশারা করলে তা গ্রহণীয় হবে।', arabic: ''),
  BukhariBab(bookNumber: 55, babNumber: 6, startHadith: 2747, endHadith: 2747, title: 'ওয়ারিসের জন্য অসীয়াত নেই।', arabic: ''),
  BukhariBab(bookNumber: 55, babNumber: 7, startHadith: 2748, endHadith: 2748, title: 'মৃত্যুর প্রাক্কালে দান খায়রাত করা।', arabic: ''),
  BukhariBab(bookNumber: 55, babNumber: 8, startHadith: 2749, endHadith: 2749, title: 'মহান আল্লাহর বাণীঃ ঋণ আদায় ও অসীয়াত পূর্ণ করার পর মৃতের সম্পত্তি ভাগ হবে।', arabic: ''),
  BukhariBab(bookNumber: 55, babNumber: 9, startHadith: 2750, endHadith: 2751, title: 'আল্লাহ্ তা‘আলার বাণীঃ ঋণ পরিশোধ ও অসীয়াত পূরণ করার পর মৃতের সম্পত্তি বণ্টন করতে হবে এর ব্যাখ্যা।', arabic: ''),
  BukhariBab(bookNumber: 55, babNumber: 10, startHadith: 2752, endHadith: 2752, title: 'যখন আত্মীয়-স্বজনের জন্য ওয়াক্ফ বা অসীয়াত করা হয় এবং আত্মীয় কারা?', arabic: ''),
  BukhariBab(bookNumber: 55, babNumber: 11, startHadith: 2753, endHadith: 2753, title: 'স্ত্রীলোক ও সন্তানাদি আত্মীয়ের মধ্যে কি?', arabic: ''),
  BukhariBab(bookNumber: 55, babNumber: 12, startHadith: 2754, endHadith: 2755, title: 'ওয়াক্ফকারী তার ওয়াকফ দ্বারা উপকার গ্রহণ করতে পারে কি?', arabic: ''),
  BukhariBab(bookNumber: 55, babNumber: 13, startHadith: 2756, endHadith: 2756, title: 'কেউ যদি বলে আমার এই জমিটি কিংবা বাগানটি আমার মায়ের পক্ষ থেকে আল্লাহর ওয়াস্তে সদাকাহ তবে তা জায়িয, যদিও তা কার জন্য তার বর্ণনা না দেয়।', arabic: ''),
  BukhariBab(bookNumber: 55, babNumber: 14, startHadith: 2757, endHadith: 2757, title: 'কোন ব্যক্তি তার সম্পদের কিছু অংশ কিংবা তার গোলামদের কতকগুলি অথবা কিছু জন্তু-জানোয়ার সদাকাহ বা ওয়াকফ করলে তা জায়িয।', arabic: ''),
  BukhariBab(bookNumber: 55, babNumber: 15, startHadith: 2758, endHadith: 2758, title: 'যে ব্যক্তি তার উকিলকে সদাকাহ প্রদান করল, অতঃপর উকিল সেটি তাকে ফিরিয়ে দিল।', arabic: ''),
  BukhariBab(bookNumber: 55, babNumber: 16, startHadith: 2759, endHadith: 2759, title: 'আল্লাহ্ তা‘আলার বাণীঃ মীরাসের মাল বণ্টনের সময় যদি কোন আত্মীয়, ইয়াতীম ও মিসকীন হাজির থাকে, তাহলে তাত্থেকে তাদেরও কিছু প্রদান করবে।', arabic: ''),
  BukhariBab(bookNumber: 55, babNumber: 17, startHadith: 2760, endHadith: 2761, title: 'অকস্মাৎ কেউ মারা গেলে তার জন্য দান-খয়রাত আর মৃতের পক্ষ থেকে তার মানৎ আদায় করা।', arabic: ''),
  BukhariBab(bookNumber: 55, babNumber: 18, startHadith: 2762, endHadith: 2762, title: 'ওয়াক্ফ ও সদাকাহ্য় সাক্ষী রাখা।', arabic: ''),
  BukhariBab(bookNumber: 55, babNumber: 19, startHadith: 2763, endHadith: 2763, title: 'আল্লাহর তা‘আলার বাণীঃ ইয়াতীমদেরকে তাদের ধন-সম্পদ দিয়ে দিবে এবং ভালোর সঙ্গে মন্দ বদল করবে না।', arabic: ''),
  BukhariBab(bookNumber: 55, babNumber: 20, startHadith: 2764, endHadith: 2765, title: 'আল্লাহ্ তাআলার বাণীঃ আর তোমরা ইয়াতিমদের পরীক্ষা করে নিবে, যে পর্যন্ত না তারা বিয়ের বয়সে পৌঁছে।', arabic: ''),
  BukhariBab(bookNumber: 55, babNumber: 21, startHadith: 2766, endHadith: 2766, title: 'আল্লাহ্ তাআলার বাণীঃ নিশ্চয় যারা ইয়াতিমের সম্পদ অন্যায়ভাবে খায়, তারা তো শুধু তাদের পেটে আগুন ভর্তি করছে।', arabic: ''),
  BukhariBab(bookNumber: 55, babNumber: 22, startHadith: 2767, endHadith: 2767, title: 'আল্লাহ্ তাআলার বাণীঃ তারা আপনাকে ইয়াতিমদের সম্পর্কে জিজ্ঞেস করে। আপনি বলুনঃ তাদের সুব্যবস্থা করা উত্তম।', arabic: ''),
  BukhariBab(bookNumber: 55, babNumber: 23, startHadith: 2768, endHadith: 2768, title: 'আবাসে কিংবা সফরে ইয়াতীমদের থেকে খেদমত গ্রহণ করা, যখন তা তাদের জন্য কল্যাণকর হয় এবং মা ও মায়ের স্বামী কর্তৃক ইয়াতীমের প্রতি নযর রাখা।', arabic: ''),
  BukhariBab(bookNumber: 55, babNumber: 24, startHadith: 2769, endHadith: 2770, title: 'যখন কেউ কোন জমি ওয়াক্ফ করে এবং তার সীমা বর্ণনা না করে তা বৈধ। সদাকাহ্ও তদ্রূপ।', arabic: ''),
  BukhariBab(bookNumber: 55, babNumber: 25, startHadith: 2771, endHadith: 2771, title: 'কোন দল যদি তাদের শরীকী জমি ওয়াক্ফ করে তা জায়িয।', arabic: ''),
  BukhariBab(bookNumber: 55, babNumber: 26, startHadith: 2772, endHadith: 2772, title: 'ওয়াকফ কিভাবে লিখিত হবে?', arabic: ''),
  BukhariBab(bookNumber: 55, babNumber: 27, startHadith: 2773, endHadith: 2773, title: 'গরীব, ধনী এবং মেহমানের জন্য ওয়াক্ফ করা।', arabic: ''),
  BukhariBab(bookNumber: 55, babNumber: 28, startHadith: 2774, endHadith: 2774, title: 'মসজিদের জন্য জমি ওয়াকফ করা।', arabic: ''),
  BukhariBab(bookNumber: 55, babNumber: 29, startHadith: 2775, endHadith: 2775, title: 'পশু, অশ্ব, আসবাবপত্র ও স্বর্ণ-রৌপ্য ওয়াক্ফ করা।', arabic: ''),
  BukhariBab(bookNumber: 55, babNumber: 30, startHadith: 2776, endHadith: 2777, title: 'ওয়াক্ফের তদারককারীর ব্যয় নির্বাহ।', arabic: ''),
  BukhariBab(bookNumber: 55, babNumber: 31, startHadith: 2778, endHadith: 2778, title: 'যখন কেউ জমি বা কূপ ওয়াকফ করে এবং অপরাপর মুসলিমদের মত সে নিজেও পানি নেয়ার শর্ত আরোপ করে।', arabic: ''),
  BukhariBab(bookNumber: 55, babNumber: 32, startHadith: 2779, endHadith: 2779, title: 'ওয়াকফকারী যদি বলে, আমি একমাত্র আল্লাহর নিকট এর মূল্য পেতে চাই তা জায়িয।', arabic: ''),
  BukhariBab(bookNumber: 55, babNumber: 33, startHadith: 2780, endHadith: 2780, title: 'আল্লাহ্ তাআলার বাণীঃ', arabic: ''),
  BukhariBab(bookNumber: 55, babNumber: 34, startHadith: 2781, endHadith: 2781, title: 'অসীয়াতকারী কর্তৃক মৃত ব্যক্তির ওয়ারিসদের অনুপস্থিতিতে মৃত ব্যক্তির দেনা পরিশোধ করা।', arabic: ''),

BukhariBab(bookNumber: 56, babNumber: 1, startHadith: 2782, endHadith: 2785, title: 'জিহাদ ও যুদ্ধের ফযীলত।', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 2, startHadith: 2786, endHadith: 2787, title: 'মানুষের মধ্যে সেই মু’মিন মুজাহিদই উত্তম, যে নিজের জান দিয়ে ও মাল দিয়ে আল্লাহর পথে জিহাদ করে।', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 3, startHadith: 2788, endHadith: 2789, title: 'পুরুষ এবং নারীর জন্য জিহাদ করার ও শাহাদাত লাভের দু‘আ।', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 4, startHadith: 2790, endHadith: 2791, title: 'আল্লাহর পথের মুজাহিদদের মর্যাদা।', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 5, startHadith: 2792, endHadith: 2794, title: 'আল্লাহর পথে সকাল-সন্ধ্যা অতিবাহিত করা। জান্নাতে তোমাদের কারো এক ধনুক পরিমিত স্থান।', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 6, startHadith: 2795, endHadith: 2796, title: 'ডাগর ডাগর চক্ষু বিশিষ্টা হুর ও তাদের গুণাবলী।', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 7, startHadith: 2797, endHadith: 2798, title: 'শাহাদাত কামনা।', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 8, startHadith: 2799, endHadith: 2800, title: 'আল্লাহর রাস্তায় সওয়ারী থেকে পতিত হয়ে কারো মৃত্যু ঘটলে, সে জিহাদকারীদের অন্তর্ভুক্ত।', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 9, startHadith: 2801, endHadith: 2802, title: 'যে ব্যক্তি আল্লাহর রাস্তায় আহত হল কিংবা বর্শা দ্বারা বিদ্ধ হল।', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 10, startHadith: 2803, endHadith: 2803, title: 'যে মহান আল্লাহর পথে আহত হয়।', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 11, startHadith: 2804, endHadith: 2804, title: 'আল্লাহ্ তাআলার বাণীঃ ‘‘বলুন, তোমরা তো আমাদের জন্য প্রতীক্ষা করছ দু’টি মঙ্গলের মধ্যে একটির।’’ (আত্-তাওবাহ ৫২)', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 12, startHadith: 2805, endHadith: 2807, title: 'আল্লাহ্ তাআলার বাণীঃ ‘‘মু‘মিনদের মধ্যে কতক আল্লাহর সাথে কৃত ওয়াদা পূর্ণ করেছে। তাদের কেউ কেউ মৃত্যুবরণ করেছে এবং কেউ কেউ প্রতীক্ষা করছে। তারা তাদের সংকল্প মোটেই পরিবর্তন করেনি।’’ (আল আহযাব ২৩)', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 13, startHadith: 2808, endHadith: 2808, title: 'যুদ্ধের আগে নেক আমল।', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 14, startHadith: 2809, endHadith: 2809, title: 'অজ্ঞাত তীর এসে যাকে হত্যা করে', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 15, startHadith: 2810, endHadith: 2810, title: 'যে ব্যক্তি আল্লাহর দ্বীনকে বুলন্দ করার উদ্দেশে জিহাদ করে।', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 16, startHadith: 2811, endHadith: 2811, title: 'আল্লাহর পথে যার দু’টি পা ধূলি-মলিন হয়।', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 17, startHadith: 2812, endHadith: 2812, title: 'আল্লাহর রাস্তায় মাথায় ধূলা লাগলে তা মুছে ফেলা।', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 18, startHadith: 2813, endHadith: 2813, title: 'যুদ্ধের এবং ধূলাবালি লাগার পর গোসল করা।', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 19, startHadith: 2814, endHadith: 2815, title: 'আল্লাহ্ তাআলার এ বাণী যাদের ব্যাপারে নাযিল হয়েছে, তাদের মর্যাদাঃ', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 20, startHadith: 2816, endHadith: 2816, title: 'শহীদের উপর ফেরেশতাদের ছায়া বিস্তার।', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 21, startHadith: 2817, endHadith: 2817, title: 'পৃথিবীতে আবার ফিরে আসার জন্য মুজাহিদদের কামনা।', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 22, startHadith: 2818, endHadith: 2818, title: 'জান্নাত হল তলোয়ারের ঝলকানির তলে।', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 23, startHadith: 2819, endHadith: 2819, title: 'জিহাদের উদ্দেশে যে সন্তান চায়।', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 24, startHadith: 2820, endHadith: 2821, title: 'যুদ্ধে সাহসিকতা ও ভীরুতা।', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 25, startHadith: 2822, endHadith: 2823, title: 'ভীরুতা থেকে আশ্রয় প্রার্থনা।', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 26, startHadith: 2824, endHadith: 2824, title: 'যুদ্ধের প্রত্যক্ষদর্শীর বর্ণনা।', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 27, startHadith: 2825, endHadith: 2825, title: 'জিহাদে গমন ওয়াজিব এবং জিহাদ ও তার নিয়্যাতের আবশ্যকতা।', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 28, startHadith: 2826, endHadith: 2827, title: 'কোন কাফির যদি কোন মুসলিমকে হত্যা করে, অতঃপর ইসলাম গ্রহণ করতঃ দীনের উপর অবিচল থেকে আল্লাহর পথে নিহত হয়।', arabic: ''),
