BukhariBab(bookNumber: 56, babNumber: 43, startHadith: 2849, endHadith: 2851, title: 'ঘোড়ার কপালের কেশদামে কল্যাণ বিধিবদ্ধ আছে ক্বিয়ামাত অবধি।', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 44, startHadith: 2852, endHadith: 2852, title: 'জিহাদ চলতে থাকবে সৎ বা অসৎ লোকের নেতৃত্বে। নাবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেছেন, ঘোটকের কপালের কেশ দামে কল্যাণ বিধিবদ্ধ আছে ক্বিয়ামাত অবধি।', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 45, startHadith: 2853, endHadith: 2853, title: 'যে ব্যক্তি আল্লাহর পথে জিহাদের উদ্দেশে ঘোড়া প্রস্তুত রাখে। মহান আল্লাহর বাণীঃ ‘‘যে জিহাদের উদ্দেশে ঘোড়া পালন করে।’’ (সূরা আল-আনফালঃ ৫২)', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 46, startHadith: 2854, endHadith: 2857, title: 'ঘোড়া ও গাধার নাম রাখা।', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 47, startHadith: 2858, endHadith: 2859, title: 'ঘোড়ার অকল্যাণ সম্পর্কে যা বলা হয়।', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 48, startHadith: 2860, endHadith: 2860, title: 'ঘোড়া তিন ধরনের মানুষের জন্য। আর আল্লাহ্ তাআলার বাণীঃ তিনি সৃষ্টি করেছেন ঘোড়া, খচ্চর ও গাধা তোমাদের আরোহণের জন্য ও শোভার জন্য এবং আরো সৃষ্টি করবেন এমন বস্ত্ত যা তোমরা জান না। (আন-নাহল ৮)', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 49, startHadith: 2861, endHadith: 2861, title: 'যে ব্যক্তি জিহাদে অন্যের পশুকে চাবুক মারে।', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 50, startHadith: 2862, endHadith: 2862, title: 'অবাধ্য পশু এবং তেজী ঘোড়ায় আরোহণ করা।', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 51, startHadith: 2863, endHadith: 2863, title: 'গনীমাতে ঘোড়ার অংশ।', arabic: ''),
