BukhariBab(bookNumber: 56, babNumber: 87, startHadith: 2913, endHadith: 2913, title: 'দুপুরের বিশ্রামকালে ইমাম থেকে তফাতে যাওয়া এবং গাছের ছায়ায় বিশ্রাম গ্রহণ করা।', arabic: ''),
