BukhariBab(bookNumber: 56, babNumber: 92, startHadith: 2923, endHadith: 2923, title: 'ছুরি সম্পর্কে যা উল্লেখ করা হয়েছে।', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 93, startHadith: 2924, endHadith: 2924, title: 'রোমীয়দের সঙ্গে যুদ্ধ সম্পর্কে যা বলা হয়েছে।', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 94, startHadith: 2925, endHadith: 2926, title: 'ইয়াহূদীদের বিরুদ্ধে যুদ্ধ', arabic: ''),
