BukhariBab(bookNumber: 56, babNumber: 96, startHadith: 2929, endHadith: 2929, title: 'যারা পশমের জুতা পরিধান করে তাদের বিরুদ্ধে যুদ্ধ।', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 97, startHadith: 2930, endHadith: 2930, title: 'পরাজয়ের সময় সঙ্গীদের সারিবদ্ধ করা, নিজের সওয়ারী থেকে নামা ও আল্লাহর সাহায্য প্রার্থনা করা।', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 98, startHadith: 2931, endHadith: 2935, title: 'মুশরিকদের পরাজিত ও প্রকম্পিত করার দু‘আ।', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 99, startHadith: 2936, endHadith: 2936, title: 'কোন মুসলিম কি আহলে কিতাবকে দ্বীনের পথ দেখাবে কিংবা তাদেরকে কুরআন শিক্ষা দিবে?', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 100, startHadith: 2937, endHadith: 2937, title: 'মুশরিকদের হিদায়াত ও মন আকর্ষণের জন্য দু‘আ।', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 101, startHadith: 2938, endHadith: 2939, title: 'ইয়াহূদী ও খৃষ্টানদের প্রতি ইসলামের দা’ওয়াত এবং কোন্ অবস্থায় তাদের সঙ্গে যুদ্ধ করা যায়? নাবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম কায়সার ও কিসরা-এর নিকট যা লিখেছিলেন এবং যুদ্ধের পূর্বে ইসলামের দাওয়াত দেয়া।', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 102, startHadith: 2940, endHadith: 2946, title: 'ইসলাম ও নবুওয়াতের দিকে নাবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর আহবান আর মানুষ যেন আল্লাহ ব্যতীত তাদের পরস্পরকে রব হিসেবে গ্রহণ না করে।', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 103, startHadith: 2947, endHadith: 2950, title: 'যে ব্যক্তি যুদ্ধ করার ইচ্ছা করে এবং অন্যদিকে আকর্ষণের মাধ্যমে তা গোপন করে রাখে আর যে বৃহস্পতিবারে সফরে বের হতে পছন্দ করে।', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 104, startHadith: 2951, endHadith: 2951, title: 'যুহরের পর সফরের উদ্দেশে বের হওয়া।', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 105, startHadith: 2952, endHadith: 2952, title: 'মাসের শেষাংশে সফরে বের হওয়া।', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 106, startHadith: 2953, endHadith: 2953, title: 'রমাযান মাসে সফরে বের হওয়া।', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 107, startHadith: 2954, endHadith: 2954, title: 'সফরকালে বিদায় দেয়া।', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 108, startHadith: 2955, endHadith: 2955, title: 'পাপ কাজের নির্দেশ না দেয়া পর্যন্ত ইমামের কথা শুনা ও আনুগত্য করা।', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 109, startHadith: 2956, endHadith: 2957, title: 'ইমামের নেতৃত্বে যুদ্ধ করা ও তাঁর মাধ্যমে নিরাপত্তা লাভ করা।', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 110, startHadith: 2958, endHadith: 2963, title: 'যুদ্ধ থেকে পালিয়ে না যাওয়ার ব্যাপারে বায়‘আত করা। আর কেউ বলেছেন, মৃত্যুর উপর বায়‘আত করা। যেহেতু আল্লাহ্ তা‘আলা ইরশাদ করেছেনঃ অবশ্যই আল্লাহ মু‘মিনদের প্রতি সন্তুষ্ট হলেন, যখন তারা বৃক্ষের নিচে আপনার আনুগত্যের শপথ গ্রহণ করল। (ফাত্হ ১৮)', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 111, startHadith: 2964, endHadith: 2964, title: 'ইমাম মানুষকে তাদের সাধ্যানুযায়ী নির্দেশ করবে।', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 112, startHadith: 2965, endHadith: 2966, title: 'নাবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম দিবার প্রারম্ভে যুদ্ধারম্ভ না করলে সূর্য ঢলা অবধি যুদ্ধারম্ভ বিলম্ব করতেন।', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 113, startHadith: 2967, endHadith: 2967, title: 'কোন ব্যক্তি কর্তৃক ইমামের অনুমতি গ্রহণ।', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 116, startHadith: 2968, endHadith: 2968, title: 'ভয়-ভীতির সময় ইমামের অগ্রগমন।', arabic: ''),
