BukhariBab(bookNumber: 56, babNumber: 119, startHadith: 2970, endHadith: 2972, title: 'পারিশ্রমিক প্রদানপূর্বক নিজের পক্ষ হতে অন্যের দ্বারা যুদ্ধ করানো এবং আল্লাহর পথে সাওয়ারী দান করা।', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 120, startHadith: 2973, endHadith: 2973, title: 'মজুরী নিয়ে জিহাদে অংশগ্রহণ করা।', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 121, startHadith: 2974, endHadith: 2976, title: 'নাবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর পতাকা সম্পর্কে যা বলা হয়েছে।', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 122, startHadith: 2977, endHadith: 2978, title: 'রাসূলুল্লাহ্ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর উক্তিঃ এক মাসের পথের দূরত্বে অবস্থিত শত্রুর মনেও আমার সম্পর্কে ভয়-ভীতি জাগরণের দ্বারা আমাকে সাহায্য করা হয়েছে।', arabic: ''),
