BukhariBab(bookNumber: 56, babNumber: 162, startHadith: 3035, endHadith: 3036, title: 'যে ব্যক্তি অশ্বোপরি দৃঢ় হয়ে থাকতে পারে না।', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 163, startHadith: 3037, endHadith: 3037, title: 'চাটাই পুড়িয়ে ক্ষতের চিকিৎসা করা, নারী কর্তৃক পিতার মুখমণ্ডল থেকে রক্ত ধৌত করা এবং ঢাল ভর্তি করে পানি বহন করা।', arabic: ''),
