BukhariBab(bookNumber: 56, babNumber: 187, startHadith: 3067, endHadith: 3069, title: 'মুশরিকরা মুসলিমের মালামাল লুণ্ঠন করে নিলে মুসলিমদের তা প্রাপ্ত হওয়া।', arabic: ''),
