BukhariBab(bookNumber: 56, babNumber: 189, startHadith: 3073, endHadith: 3073, title: 'গনীমতের মালামাল আত্মসাৎ করা।', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 190, startHadith: 3074, endHadith: 3074, title: 'স্বল্প পরিমাণ গানীমাতের মাল আত্মসাৎ করা।', arabic: ''),
