BukhariBab(bookNumber: 56, babNumber: 194, startHadith: 3077, endHadith: 3080, title: '(মক্কাহ) বিজয়ের পর হিজরাতের কোন প্রয়োজন নেই।', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 195, startHadith: 3081, endHadith: 3081, title: 'আল্লাহ তা‘আলার না-ফরমানি করলে প্রয়োজনে জিম্মী অথবা মুসলিম নারীর চুল দেখা এবং তাদেরকে বিবস্ত্র করা।', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 196, startHadith: 3082, endHadith: 3083, title: 'মুজাহিদদেরকে সাদর সম্ভাষণ জ্ঞাপন করা।', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 197, startHadith: 3084, endHadith: 3086, title: 'জিহাদ হতে ফিরে আসার কালে যা বলবে।', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 198, startHadith: 3087, endHadith: 3088, title: 'সফর হতে প্রত্যাবর্তনের পর সালাত আদায় করা।', arabic: ''),
BukhariBab(bookNumber: 56, babNumber: 199, startHadith: 3089, endHadith: 3090, title: 'সফর হতে ফিরে খাদ্য গ্রহণ প্রসঙ্গে আর (‘আবদুল্লাহ) ইব্নু ‘উমার (রাঃ) আগত মেহমানের সম্মানে সওম পালন করতেন না।', arabic: ''),
BukhariBab(bookNumber: 57, babNumber: 1, startHadith: 3091, endHadith: 3094, title: 'খুমুস নির্ধারণ প্রসঙ্গে।', arabic: ''),
BukhariBab(bookNumber: 57, babNumber: 2, startHadith: 3095, endHadith: 3095, title: 'খুমুস আদায় করা দ্বীনের অন্তর্গত।', arabic: ''),
BukhariBab(bookNumber: 57, babNumber: 3, startHadith: 3096, endHadith: 3098, title: 'নবী (সাল্লাল্লাহু ‘আলাইহি ওয়া সাল্লাম)-এর ওফাতের পর তাঁর স্ত্রীগণের ব্যয় নির্বাহ।', arabic: ''),
BukhariBab(bookNumber: 57, babNumber: 4, startHadith: 3099, endHadith: 3105, title: 'নবী (সাল্লাল্লাহু ‘আলাইহি ওয়া সাল্লাম)-এর স্ত্রীগণের ঘর এবং যে সব ঘর তাঁদের সঙ্গে সম্পর্কিত সে সবের বর্ণনা।', arabic: ''),
BukhariBab(bookNumber: 57, babNumber: 5, startHadith: 3106, endHadith: 3112, title: 'নবী (সাল্লাল্লাহু ‘আলাইহি ওয়া সাল্লাম)-এর বর্ম, লাঠি, তরবারী, পেয়ালা ও মোহর এবং তাঁর পরের খলীফাগণ সে সব দ্রব্য হতে যা ব্যবহার করেছেন, আর যেগুলোর বণ্টনের কথা অনুল্লেখিত রয়েছে এবং তাঁর চুল, পাদুকা ও পাত্র নবী (সাল্লাল্লাহু ‘আলাইহি ওয়া সাল্লাম)-এর ওফাতের পর তাঁর সাহাবীগণ ও অন্যরা যাতে শরীক ছিলেন।', arabic: ''),
BukhariBab(bookNumber: 57, babNumber: 6, startHadith: 3113, endHadith: 3113, title: 'আল্লাহর রসূল (সাল্লাল্লাহু ‘আলাইহি ওয়া সাল্লাম)-এর সময়ে আকস্মিক প্রয়োজনাদি ও মিসকীনদের জন্য গনীমতের এক পঞ্চমাংশ।', arabic: ''),
BukhariBab(bookNumber: 57, babNumber: 7, startHadith: 3114, endHadith: 3118, title: 'আল্লাহ্ তাআলার বাণীঃ নিশ্চয় এক পঞ্চমাংশ আল্লাহ্ ও রাসূলের। (৮:৪১) তা বন্টনের ইখতিয়ার রাসূলেরই।', arabic: ''),
BukhariBab(bookNumber: 57, babNumber: 8, startHadith: 3119, endHadith: 3124, title: 'নবী (সাল্লাল্লাহু ‘আলাইহি ওয়া সাল্লাম)-এর বাণীঃ তোমাদের জন্য গনীমতের মাল হালাল করা হয়েছে।', arabic: ''),
BukhariBab(bookNumber: 57, babNumber: 9, startHadith: 3125, endHadith: 3125, title: 'অভিযানে যারা উপস্থিত থেকেছে গনীমত তাদের প্রাপ্য।', arabic: ''),
BukhariBab(bookNumber: 57, babNumber: 10, startHadith: 3126, endHadith: 3126, title: 'যে ব্যক্তি গনীমত লাভের জন্য জিহাদ করে তার সওয়াব কি কম হবে?', arabic: ''),
BukhariBab(bookNumber: 57, babNumber: 11, startHadith: 3127, endHadith: 3127, title: 'ইমামের কাছে যা আসে তা বন্টন করে দেয়া এবং যে ব্যক্তি সেখানে উপস্থিত হয়নি কিংবা যে দূরে আছে তার জন্য রেখে দেয়া।', arabic: ''),
BukhariBab(bookNumber: 57, babNumber: 12, startHadith: 3128, endHadith: 3128, title: 'নবী (সাল্লাল্লাহু ‘আলাইহি ওয়া সাল্লাম) কিরূপে কুরাইযাহ ও নাযীরের মালামাল বন্টন করেছেন এবং স্বীয় প্রয়োজনে কিভাবে তাত্থেকে ব্যয় করেছেন?', arabic: ''),
BukhariBab(bookNumber: 57, babNumber: 13, startHadith: 3129, endHadith: 3129, title: 'আল্লাহর রসূল (সাল্লাল্লাহু ‘আলাইহি ওয়া সাল্লাম) ও ইসলামী নেতৃবৃন্দের সঙ্গী মুজাহিদদের সম্পদে তাদের জীবনে ও মৃত্যুর পরে বরকত সৃষ্টি সম্পর্কে।', arabic: ''),
BukhariBab(bookNumber: 57, babNumber: 14, startHadith: 3130, endHadith: 3130, title: 'যখন ইমাম কোন দূতকে কার্যোপলক্ষে প্রেরণ করেন কিংবা তাকে অবস্থান করার নির্দেশ দেন; এমতাবস্থায় তার জন্য অংশ নির্ধারিত হবে কিনা?', arabic: ''),
BukhariBab(bookNumber: 57, babNumber: 15, startHadith: 3131, endHadith: 3138, title: 'যিনি বলেন, এক পঞ্চমাংশ মুসলিমদের প্রয়োজন পূরণের উদ্দেশ্যে।', arabic: ''),
BukhariBab(bookNumber: 57, babNumber: 16, startHadith: 3139, endHadith: 3139, title: 'খুমুস পৃথক না করেই বন্দীগণের প্রতি নবী (সাল্লাল্লাহু ‘আলাইহি ওয়া সাল্লাম)-এর অনুগ্রহ।', arabic: ''),
BukhariBab(bookNumber: 57, babNumber: 17, startHadith: 3140, endHadith: 3140, title: 'খুমুস ইমামের জন্য, অধিকার রয়েছে আত্মীয়গণের কাউকে বাদ দিয়ে কাউকে প্রদানের।', arabic: ''),
BukhariBab(bookNumber: 57, babNumber: 18, startHadith: 3141, endHadith: 3155, title: 'নিহত ব্যক্তি থেকে প্রাপ্ত মালামালের খুমুস বের না করা; কেউ কাউকে হত্যা করল, অতঃপর নিহত ব্যক্তির নিকট থেকে প্রাপ্ত মালামালের খুমুস বের না করেই তা তারই প্রাপ্য আর ইমাম কর্তৃক এ রকম আদেশ দান করা।', arabic: ''),
BukhariBab(bookNumber: 58, babNumber: 1, startHadith: 3156, endHadith: 3160, title: 'জিম্মীদের নিকট থেকে জিযইয়াহ গ্রহণ এবং হারবীদের সঙ্গে যুদ্ধ বন্ধের চুক্তি।', arabic: ''),
BukhariBab(bookNumber: 58, babNumber: 2, startHadith: 3161, endHadith: 3161, title: 'মুসলিম রাষ্ট্রের ইমাম কোন জনপদের প্রধানের সঙ্গে সন্ধি করলে, তা কি অবশিষ্ট লোকেদের উপরও কার্যকর হবে?', arabic: ''),
BukhariBab(bookNumber: 58, babNumber: 3, startHadith: 3162, endHadith: 3162, title: 'আল্লাহর রসূল সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর সঙ্গে যাদের অঙ্গীকার আছে তাদের ব্যাপারে ওয়াসিয়্যাত।', arabic: ''),
BukhariBab(bookNumber: 58, babNumber: 4, startHadith: 3163, endHadith: 3165, title: 'নাবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বাহরাইনের জমি হতে যা বন্দোবস্ত দেন এবং বাহরাইনের সম্পদ ও জিযইয়াহ হতে যা দেয়ার ওয়াদা করেন। ফায় ও জিযইয়াহ কাদের মধ্যে বণ্টন করা হবে?', arabic: ''),
BukhariBab(bookNumber: 58, babNumber: 5, startHadith: 3166, endHadith: 3166, title: 'নিরপরাধ জিম্মী হত্যার পাপ।', arabic: ''),
BukhariBab(bookNumber: 58, babNumber: 6, startHadith: 3167, endHadith: 3168, title: 'আরব উপদ্বীপ হতে ইয়াহুদীদের বহিষ্করণ।', arabic: ''),
BukhariBab(bookNumber: 58, babNumber: 7, startHadith: 3169, endHadith: 3169, title: 'মুশরিকরা মুসলিমদের সাথে গাদ্দারী করলে তাদের কি ক্ষমা করা হবে?', arabic: ''),
BukhariBab(bookNumber: 58, babNumber: 8, startHadith: 3170, endHadith: 3170, title: 'অঙ্গীকার ভঙ্গকারীর বিরুদ্ধে ইমামের দু‘আ।', arabic: ''),
BukhariBab(bookNumber: 58, babNumber: 9, startHadith: 3171, endHadith: 3171, title: 'নারীগণ কর্তৃক নিরাপত্তা ও আশ্রয় প্রদান।', arabic: ''),
BukhariBab(bookNumber: 58, babNumber: 10, startHadith: 3172, endHadith: 3172, title: 'মুসলিমদের পক্ষ হতে নিরাপত্তা ও আশ্রয় প্রদান একই ব্যাপার। তা সাধারণ মুসলিমের জন্যও পালনীয়।', arabic: ''),
BukhariBab(bookNumber: 58, babNumber: 12, startHadith: 3173, endHadith: 3173, title: 'মুশরিকদের সঙ্গে দ্রব্য-সামগ্রী প্রভৃতির বদলে সন্ধি সম্পাদন এবং যে ওয়াদা পূরণ করে না তার পাপ।', arabic: ''),
BukhariBab(bookNumber: 58, babNumber: 13, startHadith: 3174, endHadith: 3174, title: 'ওয়াদা পূরণ করার ফযীলত।', arabic: ''),
BukhariBab(bookNumber: 58, babNumber: 14, startHadith: 3175, endHadith: 3175, title: 'কোন জিম্মী যাদু করলে তাকে কি ক্ষমা করা হবে?', arabic: ''),
BukhariBab(bookNumber: 58, babNumber: 15, startHadith: 3176, endHadith: 3176, title: 'বিশ্বাসঘাতকতার ব্যাপারে সতর্ক করা।', arabic: ''),
BukhariBab(bookNumber: 58, babNumber: 16, startHadith: 3177, endHadith: 3177, title: 'চুক্তিতে আবদ্ধ গোত্রের চুক্তি কিভাবে বাতিল করা যাবে?', arabic: ''),
BukhariBab(bookNumber: 58, babNumber: 17, startHadith: 3178, endHadith: 3180, title: 'যারা অঙ্গীকার করে তা ভঙ্গ করে তাদের গুনাহ।', arabic: ''),
BukhariBab(bookNumber: 58, babNumber: 18, startHadith: 3181, endHadith: 3183, title: 'পরিচ্ছেদ নাই।', arabic: ''),
BukhariBab(bookNumber: 58, babNumber: 19, startHadith: 3184, endHadith: 3184, title: 'তিন দিনের জন্য বা সুনির্দিষ্ট সময়ের জন্য সমঝোতা করা।', arabic: ''),
BukhariBab(bookNumber: 58, babNumber: 21, startHadith: 3185, endHadith: 3185, title: 'মুশরিকদের লাশ কূপে নিক্ষেপ করা এবং তাদের থেকে কোন মূল্য গ্রহণ না করা।', arabic: ''),
BukhariBab(bookNumber: 58, babNumber: 22, startHadith: 3186, endHadith: 3189, title: 'নেক বা পাপিষ্ঠ লোকের সঙ্গে কৃত ওয়াদা ভঙ্গে পাপ।', arabic: ''),
BukhariBab(bookNumber: 59, babNumber: 1, startHadith: 3190, endHadith: 3194, title: 'মহান আল্লাহর বাণীঃ তিনিই সৃষ্টির সূচনা করেন, তারপর তিনিই পুনরায় তা সৃষ্টি করবেন এটা তার জন্য খুব সহজ। (সূরা রূম ২৭)', arabic: ''),
BukhariBab(bookNumber: 59, babNumber: 2, startHadith: 3195, endHadith: 3198, title: 'সাত যমীন সম্পর্কে যা বর্ণিত হয়েছে।', arabic: ''),
BukhariBab(bookNumber: 59, babNumber: 4, startHadith: 3199, endHadith: 3204, title: 'সূর্য ও চন্দ্রের অবস্থান।', arabic: ''),
BukhariBab(bookNumber: 59, babNumber: 5, startHadith: 3205, endHadith: 3206, title: 'আল্লাহ তা‘আলার এ বাণী সম্বন্ধে যা বর্ণিত হয়েছেঃ তিনিই স্বীয় রাহমাতের বৃষ্টির পূর্বে বিস্তৃতরূপে বায়ুকে প্রেরণ করেন। (আল-ফুরকান ৪৮)', arabic: ''),
BukhariBab(bookNumber: 59, babNumber: 6, startHadith: 3207, endHadith: 3223, title: 'ফেরেশতাদের বর্ণনা।', arabic: ''),
BukhariBab(bookNumber: 59, babNumber: 7, startHadith: 3224, endHadith: 3239, title: 'তোমাদের কেউ যখন আমীন বলে আর আকাশের ফেরেশতাগণও আমীন বলে। অতঃপর একের আমীন অন্যের আমীনের সঙ্গে মিলিতভাবে উচ্চারিত হয় তখন পূর্বের পাপরাশি মুছে দেয়া হয়।', arabic: ''),
BukhariBab(bookNumber: 59, babNumber: 8, startHadith: 3240, endHadith: 3256, title: 'জান্নাতের বর্ণনা সম্পর্কে যা বলা হয়েছে আর তা হল সৃষ্ট।', arabic: ''),
BukhariBab(bookNumber: 59, babNumber: 9, startHadith: 3257, endHadith: 3257, title: 'জান্নাতের দরজাসমূহের বর্ণনা।', arabic: ''),
BukhariBab(bookNumber: 59, babNumber: 10, startHadith: 3258, endHadith: 3267, title: 'জাহান্নামের বিবরণ আর তা হচ্ছে সৃষ্ট বস্তু।', arabic: ''),
BukhariBab(bookNumber: 59, babNumber: 11, startHadith: 3268, endHadith: 3295, title: 'ইবলীস ও তার বাহিনীর বর্ণনা।', arabic: ''),
BukhariBab(bookNumber: 59, babNumber: 12, startHadith: 3296, endHadith: 3296, title: 'জ্বিন, তাদের পুরস্কার এবং শাস্তির বিবরণ।', arabic: ''),
BukhariBab(bookNumber: 59, babNumber: 14, startHadith: 3297, endHadith: 3299, title: 'মহান আল্লাহর বাণীঃ আর আল্লাহ যমীনে সকল প্রকার প্রাণী ছড়িয়ে দিয়েছেন।', arabic: ''),
BukhariBab(bookNumber: 59, babNumber: 15, startHadith: 3300, endHadith: 3313, title: 'মুসলিমের সর্বোৎকৃষ্ট মাল হল ছাগের পাল যেগুলোকে নিয়ে তারা পাহাড়ের উপর চলে যায়।', arabic: ''),
BukhariBab(bookNumber: 59, babNumber: 16, startHadith: 3314, endHadith: 3319, title: 'হারামে হত্যাযোগ্য পাঁচ প্রকারের অনিষ্টকারী প্রাণী।', arabic: ''),
BukhariBab(bookNumber: 59, babNumber: 17, startHadith: 3320, endHadith: 3325, title: 'পানীয় দ্রব্যে মাছি পড়লে ডুবিয়ে দেবে। কারণ তার এক ডানায় থাকে রোগ, অন্যটিতে থাকে আরোগ্যের উপায়।', arabic: ''),
BukhariBab(bookNumber: 60, babNumber: 1, startHadith: 3326, endHadith: 3335, title: 'আল্লাহ তা‘আলার বাণী।', arabic: ''),
BukhariBab(bookNumber: 60, babNumber: 2, startHadith: 3336, endHadith: 3336, title: 'আত্মাসমূহ সেনাবাহিনীর ন্যায় একত্রিত।', arabic: ''),
BukhariBab(bookNumber: 60, babNumber: 3, startHadith: 3337, endHadith: 3341, title: 'মহান আল্লাহর বাণীঃ ‘আর আমি নূহকে তার জাতির নিকট প্রেরণ করেছিলাম’- (হূদঃ ২৫)।', arabic: ''),
BukhariBab(bookNumber: 60, babNumber: 5, startHadith: 3342, endHadith: 3342, title: 'ইদ্রীস (আঃ)-এর বিবরণ।', arabic: ''),
BukhariBab(bookNumber: 60, babNumber: 7, startHadith: 3346, endHadith: 3348, title: 'ইয়াজুজ ও মাজুজের ঘটনা', arabic: ''),
BukhariBab(bookNumber: 60, babNumber: 8, startHadith: 3349, endHadith: 3360, title: 'মহান আল্লাহর বাণীঃ আর আল্লাহ ইবরাহীম (আঃ)-কে বন্ধুরূপে গ্রহণ করেছেন- (আন্-নিসা ১২৫)।', arabic: ''),
BukhariBab(bookNumber: 60, babNumber: 9, startHadith: 3361, endHadith: 3365, title: 'يزفّون অর্থ মানে দ্রুত বেগে চলা।', arabic: ''),
BukhariBab(bookNumber: 60, babNumber: 10, startHadith: 3366, endHadith: 3371, title: 'পরিচ্ছেদ নাই।', arabic: ''),
BukhariBab(bookNumber: 60, babNumber: 11, startHadith: 3372, endHadith: 3372, title: 'মহান আল্লাহর বাণীঃ (হে মুহাম্মাদ) আপনি তাদেরকে ইবরাহীম (আঃ)-এর মেহমানগণের ঘটনা জানিয়ে দিন। যখন তারা তাঁর নিকট এসেছিলেন- (হিজরঃ ৫১-৫২)।', arabic: ''),
BukhariBab(bookNumber: 60, babNumber: 12, startHadith: 3373, endHadith: 3373, title: 'মহান আল্লাহর বাণীঃ এবং স্মরণ করুন এই কিতাবে ইসমাঈলের কথা, অবশ্যই তিনি ছিলেন ওয়াদা পালনে সত্যনিষ্ঠ। (মারইয়ামঃ ৫৪)', arabic: ''),
BukhariBab(bookNumber: 60, babNumber: 14, startHadith: 3374, endHadith: 3374, title: 'আল্লাহ তা‘আলার বাণীঃ যখন ইয়াকূব (আঃ)-এর মৃত্যুকাল এসে হাযির হয়েছিল, তোমরা কি তখন সেখানে উপস্থিত ছিলে? যখন তিনি তাঁর সন্তানদের জিজ্ঞেস করছিলেন। (আল-বাকারাহঃ ১৩৩)', arabic: ''),
BukhariBab(bookNumber: 60, babNumber: 15, startHadith: 3375, endHadith: 3375, title: 'মহান আল্লাহর বাণীঃ স্মরণ কর লূতের কথা, তিনি তাঁর সম্প্রদায়কে বলেছিলেন; তোমরা কেন অশ্লীল কাজ করছ?', arabic: ''),
BukhariBab(bookNumber: 60, babNumber: 16, startHadith: 3376, endHadith: 3376, title: 'আল্লাহ তা‘আলার বাণীঃ অতঃপর যখন আল্লাহর ফেরেশতামন্ডলী লূত পরিবারের নিকট আসলেন, তখন তিনি বললেন, তোমরা তো অপরিচিত লোক- (হিজরঃ ৬১-৬২)।', arabic: ''),
BukhariBab(bookNumber: 60, babNumber: 17, startHadith: 3377, endHadith: 3381, title: 'আল্লাহ তা‘আলার বাণীঃ আর সামূদ জাতির প্রতি তাদেরই ভাই সালিহকে পাঠিয়েছিলাম- (হূদঃ ৬১)। আল্লাহ আরো বলেন, হিজরবাসীরা রসূলগণের প্রতি মিথ্যারোপ করেছিলো- (হিজরঃ ৮০)।', arabic: ''),
BukhariBab(bookNumber: 60, babNumber: 18, startHadith: 3382, endHadith: 3382, title: 'মহান আল্লাহর বাণীঃ যখন ইয়াকুব-এর নিকট মৃত্যু এসেছিল, তখন কি তোমরা হাযির ছিলে? (আল-বাকারাহঃ ১৩৩)', arabic: ''),
BukhariBab(bookNumber: 60, babNumber: 19, startHadith: 3383, endHadith: 3390, title: 'মহান আল্লাহর বাণীঃ নিশ্চয়ই ইউসুফ এবং তাঁর ভাইদের কাহিনীতে জিজ্ঞাসাকারীদের জন্য অনেক নিদর্শন আছে। (ইউসুফঃ ৭)', arabic: ''),
BukhariBab(bookNumber: 60, babNumber: 20, startHadith: 3391, endHadith: 3391, title: 'আল্লাহর বাণীঃ (আর স্মরণ কর) আইয়ুবের কথা। যখন তিনি তাঁর রবকে ডেকে বললেন, আমিতো দুঃখ কষ্টে পড়েছি, আর তুমিতো সর্বশ্রেষ্ঠ দয়ালু। (আম্বিয়াঃ ৮৩)।', arabic: ''),
BukhariBab(bookNumber: 60, babNumber: 21, startHadith: 3392, endHadith: 3392, title: 'আল্লাহ তা‘আলার বাণীঃ আর স্মরণ কর এই কিতাবে মূসার কথা। নিশ্চয়ই তিনি ছিলেন, বিশেষভাবে বাছাইকৃত রসূল ও নাবী।', arabic: ''),
BukhariBab(bookNumber: 60, babNumber: 22, startHadith: 3393, endHadith: 3393, title: 'মহান আল্লাহর বাণীঃ', arabic: ''),
BukhariBab(bookNumber: 60, babNumber: 24, startHadith: 3394, endHadith: 3397, title: 'মহান আল্লাহর বাণীঃ', arabic: ''),
BukhariBab(bookNumber: 60, babNumber: 25, startHadith: 3398, endHadith: 3399, title: 'মহান আল্লাহর বাণীঃ', arabic: ''),
BukhariBab(bookNumber: 60, babNumber: 27, startHadith: 3400, endHadith: 3402, title: 'মূসা (আঃ)-এর সম্পর্কিত খাযির (আঃ)-এর ঘটনা।', arabic: ''),
BukhariBab(bookNumber: 60, babNumber: 28, startHadith: 3403, endHadith: 3405, title: 'পরিচ্ছেদ নাই।', arabic: ''),
BukhariBab(bookNumber: 60, babNumber: 29, startHadith: 3406, endHadith: 3406, title: 'মহান আল্লাহর বাণীঃ তারা প্রতিমা পূজায় রত এক জাতির নিকট হাজির হয়। (আ’রাফ ১৩৮)', arabic: ''),
BukhariBab(bookNumber: 60, babNumber: 31, startHadith: 3407, endHadith: 3410, title: 'মূসা (আঃ)-এর মৃত্যু ও তৎপরবর্তী অবস্থার বর্ণনা।', arabic: ''),
BukhariBab(bookNumber: 60, babNumber: 32, startHadith: 3411, endHadith: 3411, title: 'মহান আল্লাহর বাণীঃ আর আল্লাহ্ মু‘মিনদের জন্য দৃষ্টান্ত পেশ করেছেন ফির‘আউনের স্ত্রীর। আর সে ছিল বিনয়ী ইবাদাতকারীদের অন্তর্ভুক্ত। (আত্ তাহরীম ১১-১২)', arabic: ''),
BukhariBab(bookNumber: 60, babNumber: 35, startHadith: 3412, endHadith: 3416, title: 'মহান আল্লাহর বাণীঃ আর ইউনূসও ছিলেন রাসূলদের একজন ...... তারপর একটি মাছ তাকে গিলে ফেলল, তখন তিনি নিজেকে তিরস্কার করতে লাগলেন। (আস্ সাফফাত ১৩৯-১৪২)', arabic: ''),
BukhariBab(bookNumber: 60, babNumber: 37, startHadith: 3417, endHadith: 3419, title: 'মহান আল্লাহর বাণীঃ আমি দাউদকে ‘যাবুর’ দিয়েছি। (বনী ইসরাঈল ৫৫)', arabic: ''),
BukhariBab(bookNumber: 60, babNumber: 38, startHadith: 3420, endHadith: 3420, title: 'আল্লাহর নিকট সবচেয়ে পছন্দনীয় সালাত দাউদ (আঃ)-এর সালাত ও সবচেয়ে পছন্দনীয় সওম দাউদ (আঃ)-এর সওম।', arabic: ''),
BukhariBab(bookNumber: 60, babNumber: 39, startHadith: 3421, endHadith: 3422, title: 'মহান আল্লাহর বাণীঃ এবং স্মরণ করুন আমার বান্দা দাঊদের কথা, যিনি ছিলেন খুব শক্তিশালী এবং যিনি ছিলেন অতিশয় আল্লাহ অভিমুখী।', arabic: ''),
BukhariBab(bookNumber: 60, babNumber: 40, startHadith: 3423, endHadith: 3427, title: 'মহান আল্লাহর বাণীঃ', arabic: ''),
BukhariBab(bookNumber: 60, babNumber: 41, startHadith: 3428, endHadith: 3429, title: 'মহান আল্লাহর বাণীঃ নিশ্চয়ই আমি লুকমানকে হিকমত দান করেছি। আর সে বলেছিল, শির্ক এক মহা জুলুম। (লুকমান ১২-১৩)।', arabic: ''),
BukhariBab(bookNumber: 60, babNumber: 43, startHadith: 3430, endHadith: 3430, title: 'আল্লাহর বাণীঃ', arabic: ''),
BukhariBab(bookNumber: 60, babNumber: 44, startHadith: 3431, endHadith: 3431, title: 'মহান আল্লাহর বাণী', arabic: ''),
BukhariBab(bookNumber: 60, babNumber: 45, startHadith: 3432, endHadith: 3432, title: 'মহান আল্লাহর বাণীঃ আর যখন ফেরেশতামন্ডলী বলল, হে মারইয়াম! নিশ্চয় আল্লাহ্ তোমাকে মনোনীত করেছেন।', arabic: ''),
BukhariBab(bookNumber: 60, babNumber: 46, startHadith: 3433, endHadith: 3434, title: 'মহান আল্লাহর বাণীঃ', arabic: ''),
BukhariBab(bookNumber: 60, babNumber: 47, startHadith: 3435, endHadith: 3435, title: 'অধ্যায় : মহান আল্লাহর বাণীঃ', arabic: ''),
