  BukhariBab(bookNumber: 63, babNumber: 7, startHadith: 3789, endHadith: 3791, title: 'আনসার গোত্রসমূহের মর্যাদা।', arabic: ''),
  BukhariBab(bookNumber: 63, babNumber: 8, startHadith: 3792, endHadith: 3794, title: 'আনসারগণের ব্যাপারে নাবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর উক্তিঃ তোমরা ধৈর্য অবলম্বন করবে যে পর্যন্ত না তোমরা হাওয কাউসারে আমার সঙ্গে সাক্ষাৎ কর।', arabic: ''),
  BukhariBab(bookNumber: 63, babNumber: 9, startHadith: 3795, endHadith: 3797, title: 'নাবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর দু‘আ- হে আল্লাহ্! আনসার ও মুহাজিরগণের কল্যাণ কর।', arabic: ''),
  BukhariBab(bookNumber: 63, babNumber: 10, startHadith: 3798, endHadith: 3798, title: '(আল্লাহর বাণী)- আর তারা (আনসারগণ) নিজেরা অসচ্ছল হওয়া সত্ত্বেও অন্যদেরকে নিজেদের উপর প্রাধান্য দেয়। (আল-হাশর ৯)', arabic: ''),
  BukhariBab(bookNumber: 63, babNumber: 11, startHadith: 3799, endHadith: 3801, title: 'নাবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর উক্তিঃ তাদের (আনসারদের) সৎকর্মশীলদের পক্ষ হতে (সৎ কার্য) কবূল কর, এবং তাদের ভুল-ভ্রান্তিকারীদের ক্ষমা করে দাও।', arabic: ''),
